css:
.din-claims {
  /* re-theme with these five: paper, ink, accent (fresh claims), amber (middle age), warn (old claims) */
  --din-claims-bg: oklch(0.974 0.007 95);
  --din-claims-ink: oklch(0.25 0.028 252);
  --din-claims-accent: oklch(0.55 0.085 192);
  --din-claims-amber: oklch(0.81 0.13 80);
  --din-claims-warn: oklch(0.57 0.17 31);

  --din-claims-card: color-mix(in oklch, var(--din-claims-bg) 35%, white);
  --din-claims-line: color-mix(in oklch, var(--din-claims-ink) 11%, transparent);
  --din-claims-soft: color-mix(in oklch, var(--din-claims-ink) 5%, transparent);
  --din-claims-mute: color-mix(in oklch, var(--din-claims-ink) 60%, var(--din-claims-bg));
  --din-claims-faint: color-mix(in oklch, var(--din-claims-ink) 38%, var(--din-claims-bg));
  --din-claims-b0: var(--din-claims-accent);
  --din-claims-b1: color-mix(in oklch, var(--din-claims-accent) 45%, var(--din-claims-amber));
  --din-claims-b2: var(--din-claims-amber);
  --din-claims-b3: color-mix(in oklch, var(--din-claims-amber) 40%, var(--din-claims-warn));
  --din-claims-b4: var(--din-claims-warn);
  --din-claims-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --din-claims-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --din-claims-out: cubic-bezier(.16, 1, .3, 1);
  --din-claims-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.6%, 1.061 22.6%, 1.067 25.4%, 1.042 29.7%, 1.003 35.4%, .989 41.6%, 1.001 57.6%, 1);

  width: 100%;
  height: var(--din-claims-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--din-claims-bg);
  color: var(--din-claims-ink);
  font: 13px/1.45 var(--din-claims-sans);
  accent-color: var(--din-claims-accent);
  box-shadow: inset 0 0 0 1px var(--din-claims-line);
  scrollbar-color: color-mix(in oklch, var(--din-claims-ink) 22%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, ol, li, dl, dt, dd) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(button:disabled) { cursor: not-allowed; }
  & :where(input) { font: inherit; color: inherit; }
  & :focus-visible { outline: 2px solid var(--din-claims-accent); outline-offset: 2px; }
  & [hidden] { display: none !important; }
}
.din-claims__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.din-claims__shell { height: 100%; display: grid; grid-template-columns: 200px minmax(0, 1fr); }
.din-claims__cap { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--din-claims-mute); }
.din-claims__eyebrow { font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--din-claims-mute); }

/* ------------------------------------------------------------------ sidebar */
.din-claims__side {
  display: flex; flex-direction: column; gap: 4px; min-height: 0; overflow: auto; scrollbar-width: thin;
  padding: 20px 14px 16px;
  border-right: 1px solid var(--din-claims-line);
  background: color-mix(in oklch, var(--din-claims-bg) 93%, var(--din-claims-ink));
}
.din-claims__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 20px;
  & svg { width: 32px; height: 32px; padding: 6px; flex: none; border-radius: 10px; background: var(--din-claims-ink); fill: none; stroke: var(--din-claims-bg); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 760; letter-spacing: -.025em; }
  & small { display: block; font-size: 11px; color: var(--din-claims-mute); }
}
.din-claims__nav {
  display: grid; gap: 2px;
  & button {
    position: relative; display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 10px;
    color: var(--din-claims-mute); font-weight: 560; transition: background-color .2s, color .2s;
    &:hover { background: var(--din-claims-soft); color: var(--din-claims-ink); }
    &[aria-current="page"] { background: var(--din-claims-card); color: var(--din-claims-ink); font-weight: 660; box-shadow: 0 1px 0 var(--din-claims-line), 0 10px 20px -14px color-mix(in oklch, var(--din-claims-ink) 50%, transparent); }
    &[aria-current="page"]::before { content: ""; position: absolute; left: -14px; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--din-claims-accent); }
  }
}
.din-claims__badge {
  margin-left: auto; min-width: 26px; padding: 1px 7px; border-radius: 99px; text-align: center;
  font: 600 11px/1.5 var(--din-claims-mono); font-variant-numeric: tabular-nums;
  background: color-mix(in oklch, var(--din-claims-accent) 14%, transparent); color: color-mix(in oklch, var(--din-claims-accent) 70%, var(--din-claims-ink));
}
.din-claims__sla {
  margin-top: auto; padding: 14px 8px 2px; border-top: 1px solid var(--din-claims-line);
  display: grid; gap: 6px;
}
.din-claims__slav { font-size: 12px; color: var(--din-claims-mute); & b { font-size: 22px; font-weight: 720; letter-spacing: -.03em; color: var(--din-claims-ink); font-variant-numeric: tabular-nums; margin-right: 2px; } }
.din-claims__slabar {
  position: relative; height: 8px; border-radius: 8px; background: var(--din-claims-soft); overflow: visible;
  & i { position: absolute; inset: 0 auto 0 0; width: 100%; border-radius: inherit; background: var(--din-claims-accent); transform-origin: left; transform: scaleX(var(--v, 0)); transition: transform .9s var(--din-claims-out), background-color .4s; }
  &.is-low i { background: var(--din-claims-warn); }
}
.din-claims__slat { position: absolute; left: 80%; top: -4px; bottom: -4px; width: 2px; border-radius: 2px; background: var(--din-claims-ink); }
.din-claims__slanote { font-size: 11.5px; color: var(--din-claims-mute); text-wrap: pretty; }

/* ------------------------------------------------------------------ main */
.din-claims__main {
  min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 14px;
  padding: 18px 20px 18px;
}
.din-claims__head { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.din-claims__title h2 { font-size: clamp(19px, 2.2cqi, 25px); font-weight: 740; letter-spacing: -.03em; line-height: 1.1; text-wrap: balance; margin-top: 3px; }
.din-claims__seg {
  display: inline-flex; padding: 3px; gap: 2px; border-radius: 11px; background: var(--din-claims-soft);
  box-shadow: inset 0 0 0 1px var(--din-claims-line);
  & button {
    padding: 6px 12px; border-radius: 8px; font-size: 12.5px; font-weight: 580; color: var(--din-claims-mute);
    transition: background-color .25s, color .25s, box-shadow .25s;
    &:hover { color: var(--din-claims-ink); }
    &[aria-checked="true"] { background: var(--din-claims-card); color: var(--din-claims-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--din-claims-ink) 18%, transparent); }
  }
}
.din-claims__seg--sm button { padding: 5px 10px; font-size: 12px; }

.din-claims__kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
.din-claims__kpi {
  padding: 11px 14px 10px; border-radius: 14px; background: var(--din-claims-card); box-shadow: inset 0 0 0 1px var(--din-claims-line);
  animation: din-claims-rise .7s var(--din-claims-out) backwards; animation-delay: calc(var(--i) * 55ms);
}
.din-claims__kv { font-size: clamp(20px, 2.5cqi, 28px); font-weight: 720; letter-spacing: -.035em; line-height: 1.15; font-variant-numeric: tabular-nums; margin-top: 2px; }
.din-claims__ks { font-size: 11.5px; color: var(--din-claims-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  & .up { color: var(--din-claims-warn); font-weight: 650; }
  & .dn { color: color-mix(in oklch, var(--din-claims-accent) 80%, var(--din-claims-ink)); font-weight: 650; }
}

.din-claims__view { min-height: 0; }
.din-claims__pipe { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr); gap: 14px; }
.din-claims__trend, .din-claims__team { display: grid; }
.din-claims__panel {
  position: relative; min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 10px; overflow: hidden;
  padding: 14px; border-radius: 16px; background: var(--din-claims-card); box-shadow: inset 0 0 0 1px var(--din-claims-line);
  animation: din-claims-rise .75s var(--din-claims-out) backwards; animation-delay: calc(var(--i, 0) * 55ms);
}
.din-claims__ph { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap;
  & h3 { font-size: 14px; font-weight: 700; letter-spacing: -.015em; text-wrap: balance; }
}
.din-claims__ph--row { align-items: center; }
.din-claims__hint { font-size: 11.5px; color: var(--din-claims-mute); text-wrap: pretty; }

/* ------------------------------------------------------------------ pipeline strip (chevrons) */
.din-claims__strip { display: flex; height: 50px; flex: none; }
.din-claims__stage {
  --notch: 9px;
  position: relative; flex: var(--n, 1) 1 0; min-width: 34px; margin-left: -5px; padding: 6px 8px 6px calc(var(--notch) + 7px);
  display: grid; align-content: center; overflow: hidden;
  clip-path: polygon(0 0, calc(100% - var(--notch)) 0, 100% 50%, calc(100% - var(--notch)) 100%, 0 100%, var(--notch) 50%);
  background: color-mix(in oklch, var(--din-claims-ink) 6%, var(--din-claims-card));
  transition: flex-grow .7s var(--din-claims-spring), background-color .25s, color .25s;
  &:first-child { margin-left: 0; padding-left: 10px; clip-path: polygon(0 0, calc(100% - var(--notch)) 0, 100% 50%, calc(100% - var(--notch)) 100%, 0 100%); border-radius: 8px 0 0 8px; }
  & span { font-size: 10px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--din-claims-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & b { font-size: 15px; font-weight: 720; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  &::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; background: var(--c); opacity: .9; }
  &:hover { background: color-mix(in oklch, var(--din-claims-ink) 11%, var(--din-claims-card)); }
  &[aria-pressed="true"] { background: var(--din-claims-ink); color: var(--din-claims-bg); & span { color: color-mix(in oklch, var(--din-claims-bg) 75%, transparent); } }
}

/* ------------------------------------------------------------------ matrix */
.din-claims__grid {
  flex: 1; min-height: 0; display: grid; gap: 3px;
  grid-template-columns: auto repeat(5, minmax(0, 1fr)) minmax(36px, .75fr);
  grid-template-rows: auto repeat(6, minmax(26px, 1fr)) auto;
}
.din-claims__gh {
  display: grid; place-items: center; padding: 3px 2px 5px; border-radius: 6px;
  font-size: 10.5px; font-weight: 650; color: var(--din-claims-mute); font-variant-numeric: tabular-nums; white-space: nowrap;
  &:is(button):hover { background: var(--din-claims-soft); color: var(--din-claims-ink); }
  &[aria-pressed="true"] { background: var(--din-claims-ink); color: var(--din-claims-bg); }
  & i { display: block; width: 14px; height: 3px; border-radius: 2px; background: var(--c); margin-top: 3px; }
}
.din-claims__rs { display: none; }
.din-claims__rh { display: flex; align-items: center; padding-right: 6px; font-size: 12px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.din-claims__tot { display: grid; place-items: center; font: 600 12px var(--din-claims-mono); font-variant-numeric: tabular-nums; color: var(--din-claims-mute); }
.din-claims__tot--g { color: var(--din-claims-ink); font-weight: 760; }
.din-claims__cell {
  --t: 0;
  position: relative; display: grid; place-items: center; border-radius: 7px;
  font: 650 13px var(--din-claims-mono); font-variant-numeric: tabular-nums;
  background: color-mix(in oklch, var(--c) calc(8% + var(--t) * 86%), var(--din-claims-card));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 22%, transparent);
  transition: background-color .55s var(--din-claims-out), color .3s, transform .35s var(--din-claims-spring), box-shadow .2s, opacity .3s;
  animation: din-claims-pop .6s var(--din-claims-spring) backwards; animation-delay: calc(240ms + var(--i) * 14ms);
  &.is-hot { color: white; }
  &:hover:not([aria-disabled="true"]) { transform: scale(1.06); z-index: 1; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 60%, transparent), 0 6px 16px -8px color-mix(in oklch, var(--c) 80%, transparent); }
  &[aria-disabled="true"] { color: var(--din-claims-faint); font-weight: 450; cursor: default; }
  &[aria-pressed="true"] { box-shadow: inset 0 0 0 2px var(--din-claims-ink), 0 0 0 2px var(--din-claims-card), 0 0 0 3px var(--din-claims-ink); z-index: 2; }
}
.din-claims__grid:has([aria-pressed="true"]) .din-claims__cell:not([aria-pressed="true"]) { opacity: .45; }
.din-claims__legend {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-size: 11px; color: var(--din-claims-mute);
  & b { font-weight: inherit; }
}
.din-claims__ramp { width: 64px; height: 8px; border-radius: 4px; background: linear-gradient(90deg, color-mix(in oklch, var(--din-claims-accent) 8%, var(--din-claims-card)), var(--din-claims-accent)); box-shadow: inset 0 0 0 1px var(--din-claims-line); }
.din-claims__lgsep { width: 1px; height: 12px; background: var(--din-claims-line); }
.din-claims__dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: var(--c); vertical-align: -0.5px; }

/* ------------------------------------------------------------------ queue */
.din-claims__q { padding-bottom: 0; }
.din-claims__qh { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
.din-claims__qt { display: grid; gap: 6px; min-width: 0;
  & h3 { font-size: 14px; font-weight: 700; display: flex; align-items: center; gap: 7px; }
}
.din-claims__count { font: 600 11px/1.6 var(--din-claims-mono); padding: 0 7px; border-radius: 99px; background: var(--din-claims-soft); color: var(--din-claims-mute); font-variant-numeric: tabular-nums; }
.din-claims__chips { display: flex; gap: 5px; flex-wrap: wrap; min-height: 22px; }
.din-claims__chip {
  display: inline-flex; align-items: center; gap: 5px; padding: 2px 4px 2px 9px; border-radius: 99px; font-size: 11.5px; font-weight: 600;
  background: color-mix(in oklch, var(--din-claims-accent) 13%, transparent); color: color-mix(in oklch, var(--din-claims-accent) 55%, var(--din-claims-ink));
  animation: din-claims-pop .45s var(--din-claims-spring) backwards;
  & button { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; &:hover { background: color-mix(in oklch, var(--din-claims-accent) 25%, transparent); } }
  & .din-claims__ic { width: 12px; height: 12px; stroke-width: 2.2; }
}
.din-claims__chip--none { background: none; color: var(--din-claims-faint); padding-left: 0; font-weight: 500; }
.din-claims__qtools { display: flex; gap: 6px; align-items: center; }
.din-claims__search {
  display: flex; align-items: center; gap: 6px; padding: 0 9px; height: 30px; border-radius: 9px; background: var(--din-claims-soft); box-shadow: inset 0 0 0 1px var(--din-claims-line);
  color: var(--din-claims-mute);
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--din-claims-accent); background: var(--din-claims-card); }
  & .din-claims__ic { width: 15px; height: 15px; }
  & input { width: 132px; border: 0; background: none; outline: none; font-size: 12.5px; &::placeholder { color: var(--din-claims-faint); } }
}
.din-claims__clear {
  height: 30px; padding: 0 11px; border-radius: 9px; font-size: 12px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--din-claims-line);
  &:hover:not(:disabled) { background: var(--din-claims-soft); }
  &:disabled { color: var(--din-claims-faint); }
}
.din-claims__table { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; margin: 0 -14px; position: relative; }
.din-claims__tr {
  display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(92px, 1fr) 70px 80px 28px; gap: 8px; align-items: center;
  padding: 7px 14px; border-top: 1px solid var(--din-claims-line);
}
.din-claims__thead {
  position: sticky; top: 0; z-index: 2; padding-block: 6px; border-top: 0; background: var(--din-claims-card);
  box-shadow: 0 1px 0 var(--din-claims-line);
  & > span { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--din-claims-mute); }
  & button { display: inline-flex; align-items: center; gap: 4px; letter-spacing: inherit; text-transform: inherit; font-weight: inherit; padding: 2px 4px; margin-left: -4px; border-radius: 5px;
    &:hover { color: var(--din-claims-ink); background: var(--din-claims-soft); }
    & i { width: 0; height: 0; border-inline: 3.5px solid transparent; border-top: 4.5px solid currentColor; opacity: 0; transition: transform .3s var(--din-claims-out), opacity .2s; }
  }
  & [aria-sort="ascending"] button, & [aria-sort="descending"] button { color: var(--din-claims-ink); & i { opacity: 1; } }
  & [aria-sort="ascending"] i { transform: rotate(180deg); }
}
.din-claims__num { text-align: right; justify-self: end; }
.din-claims__row {
  position: relative; cursor: pointer; outline-offset: -2px; transition: background-color .15s;
  &:hover { background: var(--din-claims-soft); }
  &[aria-selected="true"] { background: color-mix(in oklch, var(--din-claims-accent) 11%, transparent); box-shadow: inset 3px 0 0 var(--din-claims-accent); }
  &.is-new { animation: din-claims-flash 1.4s var(--din-claims-out); }
}
.din-claims__cid { display: grid; min-width: 0;
  & b { font: 600 12px var(--din-claims-mono); letter-spacing: -.01em; display: flex; align-items: center; gap: 5px; }
  & span { font-size: 11.5px; color: var(--din-claims-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & svg { width: 12px; height: 12px; fill: var(--din-claims-warn); stroke: var(--din-claims-warn); stroke-width: 1.6; }
}
.din-claims__stg { justify-self: start; max-width: 100%; padding: 2px 8px; border-radius: 6px; font-size: 11px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; background: var(--din-claims-soft); }
.din-claims__age { display: grid; gap: 3px; font: 600 12px var(--din-claims-mono); font-variant-numeric: tabular-nums;
  & i { height: 4px; border-radius: 4px; background: var(--c); width: calc(var(--w) * 100%); min-width: 3px; }
}
.din-claims__res { font: 550 12px var(--din-claims-mono); font-variant-numeric: tabular-nums; text-align: right; }
.din-claims__av {
  width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; font-size: 10px; font-weight: 700; letter-spacing: .02em;
  background: color-mix(in oklch, var(--din-claims-ink) calc(10% + var(--h, 0) * 4%), var(--din-claims-card)); color: var(--din-claims-ink);
}
.din-claims__empty { padding: 26px 14px; text-align: center; color: var(--din-claims-mute); text-wrap: pretty; }

/* scroll-driven fade on the queue rows, scoped to the queue's own scroller */
@supports (animation-timeline: view()) {
  .din-claims__tbody .din-claims__row { animation: din-claims-edge linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
}

/* ------------------------------------------------------------------ drawer */
.din-claims__drawer {
  position: absolute; z-index: 5; inset: 0 0 0 auto; width: min(340px, 94%);
  display: flex; flex-direction: column; background: var(--din-claims-card);
  border-left: 1px solid var(--din-claims-line); box-shadow: -24px 0 40px -28px color-mix(in oklch, var(--din-claims-ink) 60%, transparent);
  transform: translateX(104%); visibility: hidden;
  transition: transform .5s var(--din-claims-out), visibility 0s .5s;
  &.is-open { transform: none; visibility: visible; transition: transform .5s var(--din-claims-out), visibility 0s; }
}
.din-claims__dh { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; padding: 14px 14px 10px; border-bottom: 1px solid var(--din-claims-line);
  & h3 { font: 700 17px var(--din-claims-mono); letter-spacing: -.03em; margin-top: 2px; }
}
.din-claims__x { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; color: var(--din-claims-mute); &:hover { background: var(--din-claims-soft); color: var(--din-claims-ink); } }
.din-claims__dbody { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 12px 14px; display: grid; align-content: start; gap: 12px; }
.din-claims__facts { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 12px;
  & dt { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--din-claims-mute); }
  & dd { font-weight: 600; font-variant-numeric: tabular-nums; }
}
.din-claims__tl { display: grid; gap: 0; position: relative;
  & li { position: relative; display: grid; grid-template-columns: 18px 1fr auto; gap: 8px; align-items: start; padding: 0 0 12px; font-size: 12px;
    animation: din-claims-rise .5s var(--din-claims-out) backwards; animation-delay: calc(var(--i) * 50ms);
    &::before { content: ""; width: 10px; height: 10px; margin: 3px 0 0 4px; border-radius: 50%; background: var(--din-claims-card); box-shadow: inset 0 0 0 2px var(--din-claims-faint); }
    &:not(:last-child)::after { content: ""; position: absolute; left: 8px; top: 15px; bottom: 1px; width: 2px; background: var(--din-claims-line); }
