const NS = 'http://www.w3.org/2000/svg';
const P = 'din-claims__';
const OUT = 'cubic-bezier(.16,1,.3,1)';

/* ------------------------------------------------------------------ data
   A seeded generator so the inventory is identical on every mount. The matrix, strip,
   KPIs, SLA meter, trend's final week and adjuster loads are all counted from this one
   claims array, so they can never disagree. */
let sd = 4417;
const rnd = () => { sd = (sd + 0x6D2B79F5) | 0; let t = Math.imul(sd ^ (sd >>> 15), 1 | sd); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
const pick = (a) => a[Math.floor(rnd() * a.length)];
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const ASOF = Date.UTC(2026, 9, 2), DAY = 864e5;
const fmtD = (t) => { const d = new Date(t); return d.getUTCDate() + ' ' + MON[d.getUTCMonth()]; };

const STAGES = [
  { n: 'FNOL', s: 'FNOL', long: 'First notice of loss', c: 19, lo: 0, hi: 9, p: 1.3 },
  { n: 'Triage', s: 'Triage', long: 'Triage & coverage check', c: 23, lo: 2, hi: 30, p: 1.2 },
  { n: 'Investigation', s: 'Invest.', long: 'Investigation', c: 33, lo: 9, hi: 152, p: 1.5 },
  { n: 'Awaiting docs', s: 'Docs', long: 'Awaiting documents', c: 27, lo: 14, hi: 128, p: 1.25 },
  { n: 'Settlement', s: 'Settle', long: 'Settlement offer', c: 26, lo: 21, hi: 118, p: 1.35 },
  { n: 'Payment', s: 'Pay', long: 'Payment authorised', c: 20, lo: 26, hi: 104, p: 1.6 }
];
const BUCKETS = [{ n: '0–7d', long: '0 to 7 days', hi: 7 }, { n: '8–30d', long: '8 to 30 days', hi: 30 }, { n: '31–60d', long: '31 to 60 days', hi: 60 },
  { n: '61–90d', long: '61 to 90 days', hi: 90 }, { n: '90d+', long: 'over 90 days', hi: 1e9 }];
const bk = (d) => BUCKETS.findIndex((b) => d <= b.hi);
const BC = (i) => 'var(--din-claims-b' + i + ')';
const LINES = {
  motor: { n: 'Motor', lo: 650, hi: 26000, causes: ['Rear-end collision', 'Windscreen damage', 'Vehicle theft', 'Car park damage', 'Third-party injury', 'Flood damage to vehicle'] },
  home: { n: 'Home', lo: 900, hi: 68000, causes: ['Escape of water', 'Storm damage', 'Burglary', 'Accidental damage', 'Subsidence', 'Kitchen fire'] },
  travel: { n: 'Travel', lo: 140, hi: 9500, causes: ['Trip cancellation', 'Medical treatment abroad', 'Lost baggage', 'Missed connection'] }
};
const ADJ = ['Priya Natesan', 'Owen Faraday', 'Lucia Brand', 'Tomasz Weir', 'Ama Osei', 'Rhys Calloway'];
const ADJW = [1, 1.1, 0.75, 1.2, 1.45, 0.85];
const ini = (n) => n.split(' ').map((w) => w[0]).join('');
const FIRST = ['Hannah', 'Callum', 'Imogen', 'Kwame', 'Sofia', 'Declan', 'Mei', 'Rowan', 'Aisha', 'Felix', 'Niamh', 'Joel', 'Ines', 'Marcus', 'Yara', 'Elliot', 'Freya', 'Dev', 'Orla', 'Tobias', 'Leah', 'Samir', 'Greta', 'Ravi'];
const LAST = ['Whitcombe', 'Adebayo', 'Lindqvist', 'Harrow', 'Okafor', 'Pennington', 'Sato', 'McAllister', 'Varga', 'Ellery', 'Moreau', 'Castellan', 'Breen', 'Iqbal', 'Thornbury', 'Rasmussen', 'Duffy', 'Kowalczyk', 'Ashby', 'Nakamura'];
const wpick = (w) => { let r = rnd() * w.reduce((a, b) => a + b, 0); for (let i = 0; i < w.length; i++) { r -= w[i]; if (r < 0) return i; } return w.length - 1; };

const claims = [];
STAGES.forEach((S, si) => {
  for (let i = 0; i < S.c; i++) {
    const r = rnd();
    const line = r < 0.55 ? 'motor' : r < 0.89 ? 'home' : 'travel';
    const L = LINES[line];
    const age = Math.round(S.lo + (S.hi - S.lo) * Math.pow(rnd(), S.p));
    const res = Math.round((L.lo + (L.hi - L.lo) * Math.pow(rnd(), 2.4)) / 10) * 10;
    const w = Array.from({ length: si }, () => 0.4 + rnd());
    const tot = w.reduce((a, b) => a + b, 0) + 0.6 + rnd() * 0.8;
    let acc = 0; const enter = [0];
    for (let j = 0; j < si; j++) { acc += w[j]; enter.push(Math.round(age * acc / tot)); }
    claims.push({ line, age, res, stage: si, enter, adj: wpick(ADJW), who: pick(FIRST) + ' ' + pick(LAST), cause: pick(L.causes), flag: rnd() < 0.06, closed: false });
  }
});
claims.sort((a, b) => b.age - a.age);
let serial = 3871;
claims.forEach((c) => { c.id = 'HM-26-' + String(serial).padStart(5, '0'); serial += 1 + Math.floor(rnd() * 23); });
const byId = new Map(claims.map((c) => [c.id, c]));

/* 26 weekly snapshots per line and age band, walked backwards from today's counts */
const WEEKS = 26, LK = ['motor', 'home', 'travel'];
const counts = (line) => { const a = [0, 0, 0, 0, 0]; claims.forEach((c) => { if (!c.closed && (line === 'all' || c.line === line)) a[bk(c.age)]++; }); return a; };
const DRIFT = [-0.004, 0.002, 0.007, 0.015, 0.026];
const hist = {};
LK.forEach((lk) => {
  hist[lk] = counts(lk).map((v, b) => {
    const a = new Array(WEEKS); a[WEEKS - 1] = v; let x = v;
    for (let w = WEEKS - 2; w >= 0; w--) { x = Math.max(0, x * (1 - DRIFT[b]) + (rnd() - 0.5) * Math.max(1.4, v * 0.12)); a[w] = Math.round(x); }
    return a;
  });
});

/* ------------------------------------------------------------------ state */
const st = { view: 'pipe', line: 'all', stage: -1, bucket: -1, adj: -1, q: '', sort: 'age', dir: -1, sel: null, range: 12, hide: new Set() };
const inLine = (c) => !c.closed && (st.line === 'all' || c.line === st.line);
const open = () => claims.filter(inLine);
const series = () => {
  const live = counts(st.line), lines = st.line === 'all' ? LK : [st.line];
  return BUCKETS.map((_, b) => { const a = new Array(WEEKS).fill(0); lines.forEach((lk) => hist[lk][b].forEach((v, w) => { a[w] += v; })); a[WEEKS - 1] = live[b]; return a; });
};
const fmtK = (v) => '£' + Math.round(v).toLocaleString('en-GB');
const fmtM = (v) => v >= 1e6 ? '£' + (v / 1e6).toFixed(2) + 'M' : '£' + (v / 1e3).toFixed(1) + 'k';
const esc = (s) => String(s).replace(/[&<>"]/g, (m) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[m]));

function tween(el, to, fmt) {
  const from = el._v == null ? 0 : el._v; el._v = to;
  if (RM || from === to) { el.textContent = fmt(to); return; }
  const t0 = performance.now(), d = 620;
  const step = (t) => {
    if (!root.isConnected) return;
    if (el._v !== to) return;
    const k = Math.min(1, (t - t0) / d), e = 1 - Math.pow(1 - k, 3);
    el.textContent = fmt(from + (to - from) * e);
    if (k < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}
function toast(msg) {
  const host = $('[data-toast]'), t = document.createElement('div');
  t.className = P + 'tst'; t.textContent = msg; host.append(t);
  while (host.children.length > 2) host.firstElementChild.remove();
  setTimeout(() => { t.classList.add('is-out'); setTimeout(() => t.remove(), 360); }, 2600);
}

/* ------------------------------------------------------------------ strip + matrix (built once, updated in place) */
const strip = $('[data-strip]'), grid = $('[data-grid]'), hint = $('.' + P + 'mx .' + P + 'hint');
const HINT0 = hint.textContent;
grid.setAttribute('role', 'group');
STAGES.forEach((S, si) => {
  const b = document.createElement('button');
  b.type = 'button'; b.className = P + 'stage'; b.dataset.s = si; b.setAttribute('aria-pressed', 'false');
  b.innerHTML = '<span>' + S.s + '</span><b>0</b>';
  strip.append(b);
});
const mk = (tag, cls, html) => { const e = document.createElement(tag); e.className = cls; if (html != null) e.innerHTML = html; return e; };
grid.append(mk('span', P + 'gh', ''));
BUCKETS.forEach((B, j) => {
  const h = mk('button', P + 'gh', B.n + '<i></i>');
  h.type = 'button'; h.dataset.b = j; h.style.setProperty('--c', BC(j)); h.setAttribute('aria-pressed', 'false'); h.title = 'Show claims open ' + B.long;
  grid.append(h);
});
grid.append(mk('span', P + 'gh', 'Total'));
const cells = [];
STAGES.forEach((S, si) => {
  grid.append(mk('span', P + 'rh', '<span class="' + P + 'rl">' + S.n + '</span><span class="' + P + 'rs">' + S.s + '</span>'));
  cells[si] = [];
  BUCKETS.forEach((B, j) => {
    const c = mk('button', P + 'cell', '0');
    c.type = 'button'; c.dataset.s = si; c.dataset.b = j; c.tabIndex = si === 0 && j === 0 ? 0 : -1;
    c.style.setProperty('--c', BC(j)); c.style.setProperty('--i', si * 5 + j); c.setAttribute('aria-pressed', 'false');
    cells[si][j] = c; grid.append(c);
  });
  grid.append(mk('span', P + 'tot', '0'));
});
grid.append(mk('span', P + 'rh', 'Total'));
for (let j = 0; j < 6; j++) grid.append(mk('span', P + 'tot' + (j === 5 ? ' ' + P + 'tot--g' : ''), '0'));
const rowTots = $$('.' + P + 'tot', grid);

function renderMatrix() {
  const inv = open(), m = STAGES.map(() => BUCKETS.map(() => ({ n: 0, res: 0, old: 0 })));
  inv.forEach((c) => { const x = m[c.stage][bk(c.age)]; x.n++; x.res += c.res; x.old = Math.max(x.old, c.age); });
  const max = Math.max(1, ...m.flat().map((x) => x.n));
  const colT = [0, 0, 0, 0, 0];
  STAGES.forEach((S, si) => {
    let rt = 0, ageSum = 0;
    BUCKETS.forEach((B, j) => {
      const x = m[si][j], c = cells[si][j];
      rt += x.n; colT[j] += x.n;
      const t = x.n / max;
