  $('[data-ks="res"]').textContent = 'Avg ' + fmtK(n ? res / n : 0) + ' per claim';
  $('[data-ks="aged"]').innerHTML = aged + ' claims · <span class="' + (aged / Math.max(n, 1) > 0.2 ? 'up' : 'dn') + '">target ≤ 20%</span>';
  $('[data-ks="med"]').textContent = oldest ? 'Oldest ' + oldest.age + 'd · ' + oldest.id : '—';
