/* ------------------------------------------------------------------ trend */
const plot = $('[data-plot]'), tsvg = $('[data-tsvg]'), tip = $('[data-tip]');
let T = null;
const niceMax = (v) => { const raw = Math.max(v, 4) / 4, p = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / p; const s = (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * p; return { max: Math.ceil(v / s) * s || s * 4, step: s }; };
const sv = (tag, a) => { const e = document.createElementNS(NS, tag); for (const k in a) e.setAttribute(k, a[k]); return e; };
function renderTrend(enter) {
  const W = plot.clientWidth, H = plot.clientHeight;
  if (!W || !H) return;
  const S = series(), n = st.range, off = WEEKS - n;
  const order = [4, 3, 2, 1, 0].filter((b) => !st.hide.has(b));
  const m = { l: 34, r: 14, t: 12, b: 24 };
  const tot = Array.from({ length: n }, (_, w) => order.reduce((a, b) => a + S[b][off + w], 0));
  const { max, step } = niceMax(Math.max(...tot));
  const X = (w) => m.l + (W - m.l - m.r) * (n === 1 ? 0 : w / (n - 1)), Y = (v) => H - m.b - (H - m.t - m.b) * v / max;
  tsvg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  tsvg.replaceChildren();
  const ax = sv('g', { class: 'ax' });
  for (let v = 0; v <= max + 1e-9; v += step) {
    ax.append(sv('line', { x1: m.l, x2: W - m.r, y1: Y(v), y2: Y(v) }));
    const t = sv('text', { x: m.l - 8, y: Y(v) + 3.5, 'text-anchor': 'end' }); t.textContent = Math.round(v); ax.append(t);
  }
  const every = Math.ceil(n / Math.max(2, Math.floor((W - m.l) / 70)));
  for (let w = n - 1; w >= 0; w -= every) {
    const t = sv('text', { x: X(w), y: H - 6, 'text-anchor': w === n - 1 ? 'end' : 'middle' });
    t.textContent = fmtD(ASOF - (n - 1 - w) * 7 * DAY); ax.append(t);
  }
  tsvg.append(ax);
  const ar = sv('g', { class: 'ar' + (enter && !RM ? ' enter' : '') });
  const base = new Array(n).fill(0), tops = {};
  order.forEach((b) => {
    const top = base.map((v, w) => v + S[b][off + w]);
    const up = top.map((v, w) => X(w).toFixed(1) + ',' + Y(v).toFixed(1));
    const dn = base.map((v, w) => X(w).toFixed(1) + ',' + Y(v).toFixed(1)).reverse();
    ar.append(sv('path', { d: 'M' + up.join('L') + 'L' + dn.join('L') + 'Z', fill: BC(b), 'fill-opacity': 0.88 }));
    ar.append(sv('path', { class: 'ln', d: 'M' + up.join('L') }));
