  tsvg.append(ar);
  const cr = sv('g', { class: 'cr' }); const vl = sv('line', { y1: m.t, y2: H - m.b }); cr.append(vl);
  const dots = order.map((b) => { const c = sv('circle', { r: 3.5, stroke: BC(b) }); cr.append(c); return c; });
  tsvg.append(cr);
  T = { n, off, S, order, tops, X, Y, vl, dots, m, W, H, tot, idx: n - 1 };
  const a0 = S[4][off], a1 = S[4][WEEKS - 1];
  $('[data-trendnote]').textContent = st.hide.has(4) ? 'Showing ' + order.length + ' of 5 age bands.' :
    '90d+ band ' + (a1 >= a0 ? 'up' : 'down') + ' from ' + a0 + ' to ' + a1 + ' claims over ' + n + ' weeks' + (a0 ? ' (' + (a1 >= a0 ? '+' : '') + Math.round((a1 - a0) / a0 * 100) + '%)' : '') + '.';
  renderKeys(S);
}
function showCross(i) {
  if (!T) return;
  i = Math.max(0, Math.min(T.n - 1, i)); T.idx = i;
  const x = T.X(i);
  T.vl.setAttribute('x1', x); T.vl.setAttribute('x2', x);
  T.order.forEach((b, k) => { T.dots[k].setAttribute('cx', x); T.dots[k].setAttribute('cy', T.Y(T.tops[b][i])); });
  tsvg.classList.add('is-hover');
  const wk = ASOF - (T.n - 1 - i) * 7 * DAY;
  tip.innerHTML = '<p><span>Week ending ' + fmtD(wk) + '</span></p>' + T.order.map((b) => '<p><span><i style="--c:' + BC(b) + '"></i>' + BUCKETS[b].n + '</span><b>' + T.S[b][T.off + i] + '</b></p>').join('') +
    '<p class="tot"><span>Open</span><b>' + T.tot[i] + '</b></p>';
  tip.hidden = false;
  const tw = tip.offsetWidth, th = tip.offsetHeight;
  const left = x + 14 + tw > T.W ? x - 14 - tw : x + 14;
  tip.style.transform = 'translate(' + Math.max(0, left) + 'px,' + Math.max(0, Math.min(T.H - th, T.Y(T.tot[i]) - th / 2)) + 'px)';
}
function hideCross() { tsvg.classList.remove('is-hover'); tip.hidden = true; }
tsvg.setAttribute('tabindex', '0');
tsvg.addEventListener('pointermove', (e) => {
  if (!T) return;
  const r = tsvg.getBoundingClientRect(), x = e.clientX - r.left;
  showCross(Math.round((x - T.m.l) / ((T.W - T.m.l - T.m.r) / Math.max(1, T.n - 1))));
