function renderKeys(S) {
  const box = $('[data-keys]');
  if (!box.children.length) {
    box.innerHTML = BUCKETS.map((B, b) => '<button type="button" class="' + P + 'key" data-key="' + b + '" aria-pressed="true" style="--c:' + BC(b) + '"><i></i>' + B.n + ' <small></small></button>').join('');
  }
  $$('[data-key]', box).forEach((k) => { const b = +k.dataset.key; k.setAttribute('aria-pressed', st.hide.has(b) ? 'false' : 'true'); k.querySelector('small').textContent = S[b][WEEKS - 1]; });
}

/* ------------------------------------------------------------------ adjusters */
function renderTeam() {
