  $('[data-adj]').innerHTML = data.map((r, i) => '<li class="' + P + 'arow" style="--i:' + i + '"><span class="' + P + 'av" style="--h:' + r.j + '">' + ini(r.name) + '</span>' +
    '<div><h4>' + r.name + '</h4><p>' + fmtM(r.res) + ' reserves · oldest ' + r.old + 'd</p></div>' +
    '<div class="' + P + 'bar" role="img" aria-label="' + r.b.map((v, b) => v + ' aged ' + BUCKETS[b].n).join(', ') + '">' +
    r.b.map((v, b) => (v ? '<i style="--w:' + (v / max).toFixed(4) + ';--c:' + BC(b) + ';--i:' + i + '" title="' + BUCKETS[b].n + ': ' + v + ' claim' + (v === 1 ? '' : 's') + '"></i>' : '')).join('') +
    '<span class="' + P + 'cap30" style="left:' + (30 / max * 100).toFixed(2) + '%" title="Target load: 30 files"></span></div>' +
    '<p class="' + P + 'aload">' + r.n + '<small>' + (r.n > 30 ? (r.n - 30) + ' over target' : 'open files') + '</small></p>' +
    '<button type="button" class="' + P + 'abtn" data-viewadj="' + r.j + '">View queue</button></li>').join('');
