/* ------------------------------------------------------------------ orchestration */
function renderAll(animate) {
  renderMatrix(); renderKpis(); renderChips(); renderList(animate);
  if (st.view === 'trend') renderTrend(false);
  if (st.view === 'team') renderTeam();
  if (st.sel && byId.get(st.sel) && !byId.get(st.sel).closed) fillDrawer();
}
function setView(v) {
  st.view = v;
  $$('[data-nav]').forEach((b) => { if (b.dataset.nav === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('[data-view]').forEach((el) => { el.hidden = el.dataset.view !== v; });
  if (v !== 'pipe') closeDrawer();
  if (v === 'trend') requestAnimationFrame(() => { if (!root.isConnected) return; renderTrend(true); });
  if (v === 'team') renderTeam();
}

root.addEventListener('click', (e) => {
  const t = e.target.closest('button, [role="row"]');
  if (!t || !root.contains(t)) return;
  if (t.matches('[data-nav]')) { setView(t.dataset.nav); return; }
  if (t.matches('[data-line]')) {
    if (t.getAttribute('aria-checked') === 'true') return;
    st.line = t.dataset.line;
    $$('[data-line]').forEach((b) => b.setAttribute('aria-checked', b === t ? 'true' : 'false'));
    renderAll(true); if (st.view === 'trend') renderTrend(true);
    return;
  }
  if (t.matches('.' + P + 'stage')) { const s = +t.dataset.s; const on = st.stage === s && st.bucket < 0; st.stage = on ? -1 : s; st.bucket = -1; renderMatrix(); renderChips(); renderList(true); return; }
  if (t.matches('button.' + P + 'gh')) { const b = +t.dataset.b; const on = st.bucket === b && st.stage < 0; st.bucket = on ? -1 : b; st.stage = -1; renderMatrix(); renderChips(); renderList(true); return; }
  if (t.matches('.' + P + 'cell')) {
    if (t.getAttribute('aria-disabled') === 'true') return;
    const s = +t.dataset.s, b = +t.dataset.b, on = st.stage === s && st.bucket === b;
    st.stage = on ? -1 : s; st.bucket = on ? -1 : b;
    cells.flat().forEach((c) => { c.tabIndex = c === t ? 0 : -1; });
    renderMatrix(); renderChips(); renderList(true); return;
  }
  if (t.matches('[data-unchip]')) { if (t.dataset.unchip === 'adj') st.adj = -1; else { st.stage = -1; st.bucket = -1; } renderMatrix(); renderChips(); renderList(true); return; }
  if (t.matches('[data-clear]')) { st.stage = st.bucket = st.adj = -1; st.q = ''; $('[data-q]').value = ''; renderMatrix(); renderChips(); renderList(true); return; }
  if (t.matches('[data-sort]')) { const k = t.dataset.sort; st.dir = st.sort === k ? -st.dir : (k === 'id' ? 1 : -1); st.sort = k; renderList(true); return; }
  if (t.matches('[role="row"]') && t.dataset.id) { if (st.sel === t.dataset.id) closeDrawer(); else openDrawer(t.dataset.id, e.detail === 0); return; }
  if (t.matches('[data-close]')) { closeDrawer(true); return; }
  if (t.matches('[data-advance]')) {
    const c = byId.get(st.sel); if (!c) return;
    c.stage++; c.enter.push(c.age);
    if (c.stage > 5) { c.closed = true; toast(c.id + ' closed · ' + fmtK(c.res) + ' paid to ' + c.who.split(' ')[0]); closeDrawer(); renderAll(true); }
    else {
      toast(c.id + ' moved to ' + STAGES[c.stage].n);
      renderAll(true);
      const r = rows.get(c.id); if (r) { r.classList.remove('is-new'); void r.offsetWidth; r.classList.add('is-new'); setTimeout(() => r.classList.remove('is-new'), 1500); }
    }
    return;
  }
  if (t.matches('[data-reassign]')) { if (menu.hidden) openMenu(); else closeMenu(); return; }
  if (t.matches('[data-to]')) {
    const c = byId.get(st.sel), j = +t.dataset.to; closeMenu(true);
    if (!c) return;
    if (c.adj === j) { toast(c.id + ' is already with ' + ADJ[j]); return; }
    c.adj = j; toast(c.id + ' reassigned to ' + ADJ[j]); renderAll(false); return;
  }
  if (t.matches('[data-flag]')) { const c = byId.get(st.sel); if (!c) return; c.flag = !c.flag; fillDrawer(); renderList(false); toast(c.flag ? c.id + ' flagged for supervisor review' : 'Flag removed from ' + c.id); return; }
  if (t.matches('[data-range]')) {
    if (t.getAttribute('aria-checked') === 'true') return;
    st.range = +t.dataset.range; $$('[data-range]').forEach((b) => b.setAttribute('aria-checked', b === t ? 'true' : 'false'));
    hideCross(); renderTrend(true); return;
  }
  if (t.matches('[data-key]')) {
    const b = +t.dataset.key;
    if (!st.hide.has(b) && st.hide.size >= 4) { toast('At least one age band stays on the chart'); return; }
    if (st.hide.has(b)) st.hide.delete(b); else st.hide.add(b);
    hideCross(); renderTrend(false); return;
  }
  if (t.matches('[data-viewadj]')) { st.adj = +t.dataset.viewadj; st.stage = st.bucket = -1; setView('pipe'); renderMatrix(); renderChips(); renderList(false); table.scrollTop = 0; return; }
});

/* hover readout for matrix cells */
grid.addEventListener('pointerover', (e) => {
  const c = e.target.closest('.' + P + 'cell'); if (!c || !c._m) return;
  const x = c._m, S = STAGES[+c.dataset.s], B = BUCKETS[+c.dataset.b];
  hint.textContent = S.n + ' · ' + B.n + ' — ' + x.n + ' claim' + (x.n === 1 ? '' : 's') + (x.n ? ' · ' + fmtM(x.res) + ' reserves · oldest ' + x.old + 'd' : '');
});
grid.addEventListener('pointerleave', () => { hint.textContent = HINT0; });

/* keyboard: arrows within the matrix, the queue and the menu; Escape closes */
root.addEventListener('keydown', (e) => {
  const t = e.target;
  if (t.matches && t.matches('.' + P + 'cell')) {
    const s = +t.dataset.s, b = +t.dataset.b;
    const mv = { ArrowUp: [-1, 0], ArrowDown: [1, 0], ArrowLeft: [0, -1], ArrowRight: [0, 1] }[e.key];
    if (mv) {
      e.preventDefault();
      const ns = Math.max(0, Math.min(5, s + mv[0])), nb = Math.max(0, Math.min(4, b + mv[1]));
      const n = cells[ns][nb]; cells.flat().forEach((c) => { c.tabIndex = c === n ? 0 : -1; }); n.focus();
      n.dispatchEvent(new PointerEvent('pointerover', { bubbles: true }));
    }
    return;
  }
  if (t.matches && t.matches('[role="row"][data-id]')) {
    const all = $$('[role="row"][data-id]', tbody), i = all.indexOf(t);
    let n = null;
    if (e.key === 'ArrowDown') n = all[i + 1]; else if (e.key === 'ArrowUp') n = all[i - 1];
    else if (e.key === 'Home') n = all[0]; else if (e.key === 'End') n = all[all.length - 1];
    else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openDrawer(t.dataset.id, true); return; }
    if (n) { e.preventDefault(); all.forEach((r) => { r.tabIndex = r === n ? 0 : -1; }); n.focus(); if (st.sel) openDrawer(n.dataset.id, false); }
    return;
  }
  if (t.matches && t.matches('[data-to]')) {
    const items = $$('[data-to]', menu), i = items.indexOf(t);
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); items[(i + (e.key === 'ArrowDown' ? 1 : items.length - 1)) % items.length].focus(); return; }
    if (e.key === 'Tab') { closeMenu(); return; }
  }
  if (e.key === 'Escape') {
    if (!menu.hidden) { e.preventDefault(); e.stopPropagation(); closeMenu(true); return; }
    if (st.sel) { e.preventDefault(); closeDrawer(true); }
  }
});
root.addEventListener('pointerdown', (e) => { if (!menu.hidden && !e.target.closest('.' + P + 'menuwrap')) closeMenu(); });
$('[data-q]').addEventListener('input', (e) => { st.q = e.target.value.trim().toLowerCase(); renderChips(); renderList(false); });

let raf = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  cancelAnimationFrame(raf);
  raf = requestAnimationFrame(() => { if (!root.isConnected) return; if (st.view === 'trend') { hideCross(); renderTrend(false); } });
});
ro.observe(plot);

renderAll(false);

css:
.din-lossratio {
  /* re-theme with: bg, ink, accent (selection), loss (claims), cost (expenses), gain (profit) */
  --din-lossratio-bg: oklch(0.2 0.014 165);
  --din-lossratio-ink: oklch(0.95 0.012 110);
  --din-lossratio-accent: oklch(0.88 0.15 118);
  --din-lossratio-loss: oklch(0.71 0.15 33);
  --din-lossratio-cost: oklch(0.83 0.055 82);
  --din-lossratio-gain: oklch(0.79 0.1 165);

  --din-lossratio-panel: color-mix(in oklch, var(--din-lossratio-bg) 88%, var(--din-lossratio-ink));
  --din-lossratio-line: color-mix(in oklch, var(--din-lossratio-ink) 12%, transparent);
  --din-lossratio-soft: color-mix(in oklch, var(--din-lossratio-ink) 6%, transparent);
  --din-lossratio-mute: color-mix(in oklch, var(--din-lossratio-ink) 60%, var(--din-lossratio-bg));
  --din-lossratio-faint: color-mix(in oklch, var(--din-lossratio-ink) 34%, var(--din-lossratio-bg));
  --din-lossratio-pd: var(--din-lossratio-loss);
  --din-lossratio-cs: color-mix(in oklch, var(--din-lossratio-loss) 62%, var(--din-lossratio-bg));
  --din-lossratio-ib: color-mix(in oklch, var(--din-lossratio-loss) 30%, var(--din-lossratio-bg));
  --din-lossratio-er: var(--din-lossratio-cost);
  --din-lossratio-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --din-lossratio-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --din-lossratio-out: cubic-bezier(.2, .9, .25, 1);
  --din-lossratio-spring: linear(0, .008, .031 2%, .128 4.3%, .654 12.6%, .862 16.5%, .996 20.5%, 1.051 23.9%, 1.072 27.2%, 1.064 31%, 1.023 38%, 1.002 45.5%, .995 53.2%, 1.001 72%, 1);

  box-sizing: border-box;
  width: 100%;
  height: var(--din-lossratio-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background:
    radial-gradient(120% 70% at 100% 0%, color-mix(in oklch, var(--din-lossratio-accent) 7%, transparent), transparent 60%),
    var(--din-lossratio-bg);
  color: var(--din-lossratio-ink);
  font: 13px/1.45 var(--din-lossratio-sans);
  accent-color: var(--din-lossratio-accent);
  color-scheme: dark;
  scrollbar-color: color-mix(in oklch, var(--din-lossratio-ink) 22%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, dl, dt, dd) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--din-lossratio-accent); outline-offset: 2px; }
  & [hidden] { display: none !important; }
}
.din-lossratio__wrap { height: 100%; min-height: 0; display: grid; grid-template-rows: auto auto auto minmax(0, 1fr); gap: 12px; padding: 18px 20px 16px; }
.din-lossratio__eyebrow { font-size: 11px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--din-lossratio-mute); }
.din-lossratio__cap { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--din-lossratio-mute); }

/* ------------------------------------------------------------------ header */
.din-lossratio__top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }
.din-lossratio__brand { display: flex; align-items: center; gap: 12px;
  & svg { width: 38px; height: 38px; padding: 8px; flex: none; border-radius: 11px; fill: none; stroke: var(--din-lossratio-bg); stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; background: var(--din-lossratio-accent); }
  & h2 { font-size: clamp(18px, 2.1cqi, 24px); font-weight: 720; letter-spacing: -.03em; line-height: 1.1; text-wrap: balance; }
}
.din-lossratio__ctl { display: flex; gap: 8px; flex-wrap: wrap; }
.din-lossratio__seg {
  display: inline-flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--din-lossratio-soft); box-shadow: inset 0 0 0 1px var(--din-lossratio-line);
  & button { padding: 6px 11px; border-radius: 7px; font-size: 12.5px; font-weight: 580; color: var(--din-lossratio-mute); white-space: nowrap; transition: background-color .25s, color .25s;
    &:hover { color: var(--din-lossratio-ink); }
    &[aria-checked="true"] { background: var(--din-lossratio-ink); color: var(--din-lossratio-bg); }
  }
}
.din-lossratio__seg--sm button { padding: 4px 9px; font-size: 12px; }

/* ------------------------------------------------------------------ KPIs */
.din-lossratio__kpis { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); border-radius: 14px; box-shadow: inset 0 0 0 1px var(--din-lossratio-line); overflow: hidden; }
.din-lossratio__kpi {
  padding: 10px 14px 11px; display: grid; gap: 2px;
  & + & { border-left: 1px solid var(--din-lossratio-line); }
  & p { font-size: 11.5px; color: var(--din-lossratio-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; & small { font: 500 10.5px var(--din-lossratio-mono); color: var(--din-lossratio-faint); margin-left: 4px; } }
  & b { font: 680 clamp(18px, 2.2cqi, 25px)/1.1 var(--din-lossratio-sans); letter-spacing: -.03em; font-variant-numeric: tabular-nums; animation: din-lossratio-in .7s var(--din-lossratio-out) backwards; animation-delay: calc(var(--i) * 60ms); }
  & .g { color: var(--din-lossratio-gain); } & .l { color: var(--din-lossratio-loss); }
}
.din-lossratio__kpi--hero { background: color-mix(in oklch, var(--din-lossratio-accent) 9%, transparent); & b { color: var(--din-lossratio-accent); } }

/* ------------------------------------------------------------------ tabs bar */
.din-lossratio__bar { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; border-bottom: 1px solid var(--din-lossratio-line); }
.din-lossratio__tabs { display: flex; gap: 4px; margin-bottom: -1px; overflow-x: auto; scrollbar-width: none;
  & button { position: relative; padding: 8px 12px 10px; font-weight: 600; color: var(--din-lossratio-mute); white-space: nowrap; transition: color .2s;
    &::after { content: ""; position: absolute; left: 10px; right: 10px; bottom: 0; height: 2px; border-radius: 2px; background: var(--din-lossratio-accent); transform: scaleX(0); transition: transform .45s var(--din-lossratio-spring); }
    &:hover { color: var(--din-lossratio-ink); }
    &[aria-selected="true"] { color: var(--din-lossratio-ink); &::after { transform: none; } }
  }
}
.din-lossratio__sort { display: flex; align-items: center; gap: 8px; padding-bottom: 6px; font-size: 11.5px; color: var(--din-lossratio-mute); }
.din-lossratio:has([data-tab="mekko"][aria-selected="false"]) .din-lossratio__sort { visibility: hidden; }

/* ------------------------------------------------------------------ mekko view */
.din-lossratio__view { min-height: 0; }
.din-lossratio__mk { display: grid; grid-template-columns: minmax(0, 1fr) 272px; gap: 14px; }
.din-lossratio__chart { min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 8px; }
.din-lossratio__legend { display: flex; gap: 14px; flex-wrap: wrap; font-size: 11.5px; color: var(--din-lossratio-mute);
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 10px; height: 10px; border-radius: 3px; }
  & .s-pd { background: var(--din-lossratio-pd); } & .s-cs { background: var(--din-lossratio-cs); }
  & .s-ib { background: repeating-linear-gradient(45deg, var(--din-lossratio-ib) 0 2px, color-mix(in oklch, var(--din-lossratio-loss) 70%, transparent) 2px 3.5px); }
  & .s-er { background: var(--din-lossratio-er); }
}
.din-lossratio__lgnote { margin-left: auto; color: var(--din-lossratio-faint); }
.din-lossratio__plot { position: relative; flex: 1; min-height: 0; }
.din-lossratio__svg {
  position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; touch-action: pan-y;
  & text { font-family: var(--din-lossratio-sans); font-variant-numeric: tabular-nums; }
  & .grid line { stroke: var(--din-lossratio-line); }
  & .grid text { font: 500 10.5px var(--din-lossratio-mono); fill: var(--din-lossratio-faint); }
  & .zone { fill: color-mix(in oklch, var(--din-lossratio-loss) 7%, transparent); }
  & .be line { stroke: var(--din-lossratio-ink); stroke-width: 1.5; }
  & .be text { font: 650 10.5px var(--din-lossratio-sans); fill: var(--din-lossratio-ink); letter-spacing: .04em; text-transform: uppercase; }
  & .plan { stroke: var(--din-lossratio-accent); stroke-width: 1; stroke-dasharray: 2 3; }
  & .band { cursor: pointer; outline: none; transition: transform .75s var(--din-lossratio-spring), opacity .3s; }
  & .band rect.seg { transition: x .75s var(--din-lossratio-out), width .75s var(--din-lossratio-out), height .75s var(--din-lossratio-spring); }
  & .band .hit { fill: transparent; }
  & .band .sel { fill: none; stroke: var(--din-lossratio-accent); stroke-width: 2; opacity: 0; transition: opacity .25s, height .75s var(--din-lossratio-spring), width .75s var(--din-lossratio-out); }
  & .band[aria-pressed="true"] .sel { opacity: 1; }
  & .band:focus-visible .sel { opacity: 1; stroke-dasharray: 4 3; }
  & .band .lb { transition: transform .75s var(--din-lossratio-spring); }
  & .band .nm { font-size: 12.5px; font-weight: 620; fill: var(--din-lossratio-ink); }
  & .band .sub { font: 500 10.5px var(--din-lossratio-mono); fill: var(--din-lossratio-faint); }
  & .band .cor { font: 650 12px var(--din-lossratio-mono); fill: var(--din-lossratio-ink); }
  & .band .uw { font: 600 11.5px var(--din-lossratio-mono); }
  & .band .uw.g { fill: var(--din-lossratio-gain); } & .band .uw.l { fill: var(--din-lossratio-loss); }
  & .band .ends { transition: transform .75s var(--din-lossratio-out); }
  & .band.port .nm { font-weight: 760; }
  & .band.port rect.seg { opacity: .95; }
  & .s-pd { fill: var(--din-lossratio-pd); } & .s-cs { fill: var(--din-lossratio-cs); } & .s-ib { fill: url(#din-lossratio-hatch); } & .s-er { fill: var(--din-lossratio-er); }
  & .xh line { stroke: var(--din-lossratio-accent); stroke-width: 1; }
  & .xh rect { fill: var(--din-lossratio-accent); }
  & .xh text { font: 650 10.5px var(--din-lossratio-mono); fill: var(--din-lossratio-bg); }
  & .xh { opacity: 0; transition: opacity .15s; pointer-events: none; }
  &.is-hover .xh { opacity: 1; }
  &:has(.band:hover) .band:not(:hover):not([aria-pressed="true"]) { opacity: .55; }
}
.din-lossratio__hbg { fill: var(--din-lossratio-ib); }
.din-lossratio__hln { stroke: color-mix(in oklch, var(--din-lossratio-loss) 80%, transparent); stroke-width: 2.2; }
.din-lossratio__tip {
  position: absolute; left: 0; top: 0; z-index: 4; pointer-events: none; width: 216px; padding: 10px 12px; border-radius: 12px;
  background: color-mix(in oklch, var(--din-lossratio-bg) 70%, black); box-shadow: 0 0 0 1px var(--din-lossratio-line), 0 18px 40px -12px black;
  font-size: 12px;
  & h4 { font-size: 13px; font-weight: 700; margin: 0 0 6px; display: flex; justify-content: space-between; gap: 8px; & span { font: 600 12px var(--din-lossratio-mono); color: var(--din-lossratio-accent); } }
  & p { display: flex; justify-content: space-between; gap: 10px; padding: 1.5px 0; color: var(--din-lossratio-mute); & b { font: 600 12px var(--din-lossratio-mono); color: var(--din-lossratio-ink); font-variant-numeric: tabular-nums; } }
  & i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
  & .tot { margin-top: 4px; padding-top: 5px; border-top: 1px solid var(--din-lossratio-line); color: var(--din-lossratio-ink); }
}

/* detail */
.din-lossratio__detail {
  min-height: 0; overflow: auto; scrollbar-width: thin; display: flex; flex-direction: column; gap: 10px;
  padding: 14px; border-radius: 16px; background: var(--din-lossratio-panel); box-shadow: inset 0 0 0 1px var(--din-lossratio-line);
  animation: din-lossratio-in .7s var(--din-lossratio-out) .15s backwards;
  & h3 { font-size: 19px; font-weight: 720; letter-spacing: -.025em; text-wrap: balance; margin-top: -4px; }
}
.din-lossratio__dk { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 12px;
  & div { display: grid; gap: 1px; animation: din-lossratio-in .5s var(--din-lossratio-out) backwards; animation-delay: calc(var(--i) * 40ms); }
  & dt { font-size: 11px; color: var(--din-lossratio-mute); }
  & dd { font: 650 16px var(--din-lossratio-mono); letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & .g { color: var(--din-lossratio-gain); } & .l { color: var(--din-lossratio-loss); } & .a { color: var(--din-lossratio-accent); }
}
.din-lossratio__comp { position: relative; display: flex; height: 12px; border-radius: 4px; overflow: hidden; background: var(--din-lossratio-soft);
  & i { height: 100%; width: calc(var(--w) * 1%); transition: width .7s var(--din-lossratio-out); }
  & .s-pd { background: var(--din-lossratio-pd); } & .s-cs { background: var(--din-lossratio-cs); }
  & .s-ib { background: repeating-linear-gradient(45deg, var(--din-lossratio-ib) 0 2px, color-mix(in oklch, var(--din-lossratio-loss) 70%, transparent) 2px 3.5px); }
  & .s-er { background: var(--din-lossratio-er); }
  & .s-mg { background: repeating-linear-gradient(90deg, color-mix(in oklch, var(--din-lossratio-gain) 35%, transparent) 0 1px, transparent 1px 4px); }
  & .s-ov { background: var(--din-lossratio-loss); box-shadow: 0 0 10px var(--din-lossratio-loss); }
}
.din-lossratio__dnote { font-size: 12px; color: var(--din-lossratio-mute); text-wrap: pretty; & b { color: var(--din-lossratio-ink); font-weight: 600; } }
.din-lossratio__mini { position: relative; margin-top: auto; display: grid; gap: 6px; }
.din-lossratio__msvg { width: 100%; height: 118px; overflow: visible; cursor: crosshair;
  & .ax line { stroke: var(--din-lossratio-line); } & .ax text { font: 500 9.5px var(--din-lossratio-mono); fill: var(--din-lossratio-faint); }
  & .be { stroke: var(--din-lossratio-ink); stroke-dasharray: 3 3; opacity: .6; }
  & .hl { fill: color-mix(in oklch, var(--din-lossratio-accent) 10%, transparent); }
  & .ln { fill: none; stroke: var(--din-lossratio-accent); stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }
  & .ln.draw { stroke-dasharray: var(--len); stroke-dashoffset: var(--len); animation: din-lossratio-draw 1s var(--din-lossratio-out) .2s forwards; }
  & .ar { fill: color-mix(in oklch, var(--din-lossratio-accent) 12%, transparent); }
  & .pt { fill: var(--din-lossratio-bg); stroke: var(--din-lossratio-accent); stroke-width: 1.5; }
  & .pt.over { stroke: var(--din-lossratio-loss); }
  & .cr { opacity: 0; } &.is-hover .cr { opacity: 1; }
  & .cr line { stroke: var(--din-lossratio-ink); stroke-width: 1; } & .cr circle { fill: var(--din-lossratio-accent); }
}
.din-lossratio__mtip { position: absolute; top: 18px; left: 0; pointer-events: none; padding: 4px 8px; border-radius: 7px; font: 600 11px var(--din-lossratio-mono); white-space: nowrap;
  background: var(--din-lossratio-ink); color: var(--din-lossratio-bg); }

/* ------------------------------------------------------------------ trend: small multiples */
.din-lossratio__tr { display: flex; flex-direction: column; gap: 8px; }
.din-lossratio__trnote { font-size: 12px; color: var(--din-lossratio-mute); }
.din-lossratio__multi { flex: 1; min-height: 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-auto-rows: minmax(0, 1fr); gap: 10px; overflow: auto; scrollbar-width: thin; }
.din-lossratio__sm {
  position: relative; min-height: 150px; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 4px; padding: 10px 12px 8px; border-radius: 14px;
  background: var(--din-lossratio-panel); box-shadow: inset 0 0 0 1px var(--din-lossratio-line); cursor: pointer; text-align: left;
  transition: box-shadow .2s, transform .35s var(--din-lossratio-spring);
  animation: din-lossratio-in .6s var(--din-lossratio-out) backwards; animation-delay: calc(var(--i) * 55ms);
  &:hover { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--din-lossratio-accent) 50%, transparent); }
  &:active { transform: scale(.985); }
  & header { display: flex; justify-content: space-between; align-items: baseline; gap: 6px; }
  & h4 { margin: 0; font-size: 12.5px; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .v { font: 650 13px var(--din-lossratio-mono); font-variant-numeric: tabular-nums; }
  & .v.l { color: var(--din-lossratio-loss); } & .v.g { color: var(--din-lossratio-gain); }
  & svg { width: 100%; height: 100%; overflow: visible; display: block; }
  & .hl { fill: color-mix(in oklch, var(--din-lossratio-accent) 9%, transparent); }
  & .be { stroke: var(--din-lossratio-ink); stroke-dasharray: 3 3; opacity: .45; }
  & .gl { stroke: var(--din-lossratio-line); }
