css:
.din-uw {
  /* re-theme with bg, ink, accent (the main flow), win, lose and wait */
  --din-uw-bg: oklch(0.205 0.012 65);
  --din-uw-ink: oklch(0.95 0.014 85);
  --din-uw-accent: oklch(0.81 0.135 72);
  --din-uw-win: oklch(0.79 0.12 158);
  --din-uw-lose: oklch(0.68 0.14 32);
  --din-uw-wait: oklch(0.77 0.045 235);

  --din-uw-panel: color-mix(in oklch, var(--din-uw-bg) 92%, var(--din-uw-ink));
  --din-uw-raise: color-mix(in oklch, var(--din-uw-bg) 85%, var(--din-uw-ink));
  --din-uw-line: color-mix(in oklch, var(--din-uw-ink) 11%, transparent);
  --din-uw-soft: color-mix(in oklch, var(--din-uw-ink) 6%, transparent);
  --din-uw-mute: color-mix(in oklch, var(--din-uw-ink) 62%, var(--din-uw-bg));
  --din-uw-faint: color-mix(in oklch, var(--din-uw-ink) 36%, var(--din-uw-bg));
  --din-uw-l0: oklch(0.8 0.11 72);
  --din-uw-l1: oklch(0.74 0.1 25);
  --din-uw-l2: oklch(0.76 0.08 200);
  --din-uw-l3: oklch(0.8 0.1 130);
  --din-uw-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --din-uw-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --din-uw-out: cubic-bezier(.16, 1, .3, 1);
  --din-uw-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 17.2%, 1.017 20.9%, 1.043 24.6%, 1.035 30.3%, 1.004 42%, .997 52.3%, 1);

  box-sizing: border-box;
  width: 100%;
  height: var(--din-uw-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  display: grid; grid-template-rows: auto minmax(0, 1fr);
  border-radius: 18px;
  background:
    radial-gradient(90% 60% at 0% 0%, color-mix(in oklch, var(--din-uw-accent) 9%, transparent), transparent 62%),
    var(--din-uw-bg);
  color: var(--din-uw-ink);
  font: 13px/1.45 var(--din-uw-sans);
  accent-color: var(--din-uw-accent);
  color-scheme: dark;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dt, dd, ul) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--din-uw-accent); outline-offset: 2px; }
  & [hidden] { display: none !important; }
}
.din-uw__eyebrow { font-size: 11px; font-weight: 600; letter-spacing: .09em; text-transform: uppercase; color: var(--din-uw-mute); }

/* ------------------------------------------------------------------ header */
.din-uw__head { display: flex; align-items: center; justify-content: space-between; gap: 12px 18px; flex-wrap: wrap; padding: 16px 20px 12px; }
.din-uw__brand { display: flex; align-items: center; gap: 12px; min-width: 0;
  & svg { width: 38px; height: 38px; flex: none; padding: 8px; border-radius: 11px; background: var(--din-uw-accent); fill: none; stroke: var(--din-uw-bg); stroke-width: 2.1; stroke-linecap: round; }
  & h2 { font-size: clamp(18px, 2.1cqi, 24px); font-weight: 730; letter-spacing: -.03em; line-height: 1.1; text-wrap: balance; }
}
.din-uw__filters { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.din-uw__chips { display: flex; gap: 6px; flex-wrap: wrap;
  & button { display: inline-flex; align-items: center; gap: 7px; padding: 6px 11px 6px 9px; border-radius: 999px; font-size: 12.5px; font-weight: 580;
    color: var(--din-uw-mute); box-shadow: inset 0 0 0 1px var(--din-uw-line); transition: background-color .25s, color .25s, box-shadow .25s;
    & i { width: 9px; height: 9px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--c); transition: background-color .25s, transform .4s var(--din-uw-spring); }
    &:hover { color: var(--din-uw-ink); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 60%, transparent); }
    &[aria-pressed="true"] { color: var(--din-uw-ink); background: color-mix(in oklch, var(--c) 14%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 45%, transparent);
      & i { background: var(--c); transform: scale(1.1); } }
  }
}
.din-uw__seg { display: inline-flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--din-uw-soft); box-shadow: inset 0 0 0 1px var(--din-uw-line);
  & button { padding: 5px 11px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--din-uw-mute); white-space: nowrap; transition: background-color .25s, color .25s;
    &:hover { color: var(--din-uw-ink); }
    &[aria-checked="true"] { background: var(--din-uw-ink); color: var(--din-uw-bg); }
    & span { font: 600 11px var(--din-uw-mono); opacity: .75; margin-left: 2px; }
  }
}
.din-uw__seg--sm button { padding: 4px 9px; font-size: 12px; }
.din-uw__seg--xs { padding: 2px; border-radius: 8px; & button { padding: 2px 8px; font-size: 11.5px; border-radius: 6px; } }

/* ------------------------------------------------------------------ body grid */
.din-uw__body {
  min-height: 0; padding: 0 20px 18px;
  display: grid; gap: 12px;
  grid-template-columns: minmax(0, 1fr) clamp(272px, 28cqi, 330px);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "kpis kpis" "main work";
}
.din-uw__kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); border-radius: 14px; background: var(--din-uw-panel); box-shadow: inset 0 0 0 1px var(--din-uw-line); }
.din-uw__kpi {
  padding: 10px 14px 11px; min-width: 0; display: grid; gap: 1px;
  & + & { border-left: 1px solid var(--din-uw-line); }
  & p { font-size: 11.5px; font-weight: 550; color: var(--din-uw-mute); }
  & b { font: 700 clamp(19px, 2.2cqi, 26px)/1.1 var(--din-uw-sans); letter-spacing: -.035em; font-variant-numeric: tabular-nums;
    animation: din-uw-rise .8s var(--din-uw-out) backwards; animation-delay: calc(var(--i) * 55ms + 80ms); }
  & small { font-size: 11px; color: var(--din-uw-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.din-uw__kpi--hero b { color: var(--din-uw-win); }

.din-uw__main { grid-area: main; min-width: 0; min-height: 0; display: flex; flex-direction: column; border-radius: 16px; background: var(--din-uw-panel); box-shadow: inset 0 0 0 1px var(--din-uw-line); overflow: hidden; }
.din-uw__bar { display: flex; align-items: center; justify-content: space-between; gap: 6px 12px; flex-wrap: wrap; padding: 0 14px; border-bottom: 1px solid var(--din-uw-line); }
.din-uw__tabs { display: flex; gap: 2px; margin-bottom: -1px;
  & button { position: relative; padding: 11px 10px 10px; font-weight: 620; color: var(--din-uw-mute); white-space: nowrap; transition: color .2s;
    &::after { content: ""; position: absolute; inset: auto 8px 0; height: 2px; border-radius: 2px; background: var(--din-uw-accent); transform: scaleX(0); transition: transform .5s var(--din-uw-spring); }
    &:hover { color: var(--din-uw-ink); }
    &[aria-selected="true"] { color: var(--din-uw-ink); &::after { transform: none; } }
  }
}
.din-uw__hint { font-size: 11.5px; color: var(--din-uw-faint); padding: 6px 0; text-wrap: pretty; }
.din-uw__panel { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.din-uw__plot { position: relative; flex: 1; min-height: 0; }
.din-uw__svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; touch-action: pan-y;
  & text { font-family: var(--din-uw-sans); font-variant-numeric: tabular-nums; }
}

/* flow chart */
.din-uw__lk { opacity: .6; transition: opacity .3s; }
.din-uw__lk--main { fill: url(#din-uw-grad-main); }
.din-uw__lk--lose { fill: url(#din-uw-grad-lose); }
.din-uw__lk--wait { fill: url(#din-uw-grad-wait); }
.din-uw__lk--win { fill: url(#din-uw-grad-win); }
.din-uw__gs { stop-opacity: .7; }
.din-uw__gs--main { stop-color: var(--din-uw-accent); }
.din-uw__gs--lose { stop-color: var(--din-uw-lose); }
.din-uw__gs--wait { stop-color: var(--din-uw-wait); }
.din-uw__gs--win { stop-color: var(--din-uw-win); }
.din-uw__lk:hover { opacity: .85; }
.din-uw__nd { cursor: pointer; outline: none;
  & .bx { transition: filter .2s; }
  & .hit { fill: transparent; }
  & .ring { fill: none; stroke: var(--din-uw-ink); stroke-width: 1.5; opacity: 0; transition: opacity .2s; }
  &:hover .bx { filter: brightness(1.2); }
  &:focus-visible .ring { opacity: 1; stroke-dasharray: 3 3; }
  &[aria-pressed="true"] .ring { opacity: 1; }
  & .hd1 { font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; fill: var(--din-uw-mute); }
  & .hd2 { font: 720 clamp(14px, 1.8cqi, 19px) var(--din-uw-sans); letter-spacing: -.03em; fill: var(--din-uw-ink); }
  & .hd3 { font: 600 11px var(--din-uw-mono); fill: var(--din-uw-faint); }
  & .lb { font-size: 11.5px; font-weight: 600; fill: var(--din-uw-ink); paint-order: stroke; stroke: var(--din-uw-panel); stroke-width: 4px; stroke-linejoin: round; transition: opacity .25s; }
  & .lb tspan.n { font: 600 11px var(--din-uw-mono); fill: var(--din-uw-mute); }
  & .lb tspan.pc { font: 500 10.5px var(--din-uw-mono); fill: var(--din-uw-faint); }
}
.din-uw__nd--main .bx { fill: var(--din-uw-accent); }
.din-uw__nd--lose .bx { fill: var(--din-uw-lose); }
.din-uw__nd--wait .bx { fill: var(--din-uw-wait); }
.din-uw__nd--win .bx { fill: var(--din-uw-win); }
.din-uw__svg[data-flow] { & [data-glinks] { animation: din-uw-wipe 1.1s var(--din-uw-out) .15s backwards; }
  & .din-uw__nd { animation: din-uw-pop .7s var(--din-uw-spring) backwards; animation-delay: calc(var(--i) * 40ms + 60ms); transform-box: fill-box; transform-origin: 50% 50%; }
}
.din-uw__svg.is-focus { & .din-uw__lk.is-on { opacity: .8; } & .din-uw__lk:not(.is-on) { opacity: .12; } & .din-uw__nd:not(.is-on) { opacity: .4; } }
.din-uw__svg.is-compact .din-uw__nd .lb { font-size: 10.5px; }
.din-uw__focus { min-height: 38px; padding: 9px 14px 11px; border-top: 1px solid var(--din-uw-line); font-size: 12px; color: var(--din-uw-mute); text-wrap: pretty;
  & b { color: var(--din-uw-ink); font-weight: 650; } & .m { font-family: var(--din-uw-mono); color: var(--din-uw-ink); }
  & i { font-style: normal; display: inline-flex; align-items: center; gap: 5px; margin-right: 10px; white-space: nowrap; }
  & i::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--c); }
}

.din-uw__tip {
  position: absolute; left: 0; top: 0; z-index: 5; pointer-events: none; min-width: 168px; max-width: 240px; padding: 9px 11px; border-radius: 11px;
  background: color-mix(in oklch, var(--din-uw-bg) 72%, black); box-shadow: 0 0 0 1px var(--din-uw-line), 0 16px 36px -14px black;
  font-size: 12px; color: var(--din-uw-mute);
  & b { display: block; color: var(--din-uw-ink); font-weight: 680; margin-bottom: 3px; }
  & p { display: flex; justify-content: space-between; gap: 12px; & span { font-family: var(--din-uw-mono); color: var(--din-uw-ink); } }
}

/* pricing chart */
.din-uw__pp { flex-direction: row; }
.din-uw__pp .din-uw__plot { min-width: 0; }
.din-uw__psvg {
  & .ax line { stroke: var(--din-uw-line); }
  & .ax text { font: 500 10.5px var(--din-uw-mono); fill: var(--din-uw-faint); }
  & .ax .ttl { font: 600 10.5px var(--din-uw-sans); letter-spacing: .06em; text-transform: uppercase; fill: var(--din-uw-mute); }
  & .tech { stroke: var(--din-uw-ink); stroke-opacity: .5; stroke-dasharray: 2 3; }
  & .bin { transform-box: fill-box; transform-origin: 50% 100%; animation: din-uw-grow .7s var(--din-uw-out) backwards; animation-delay: calc(var(--i) * 35ms);
    & rect { fill: color-mix(in oklch, var(--din-uw-wait) 15%, transparent); } & .cap { stroke: var(--din-uw-wait); stroke-width: 2; stroke-linecap: round; } }
  & .curve { fill: none; stroke: var(--din-uw-accent); stroke-width: 2.4; stroke-linecap: round; }
  & .mcurve { fill: none; stroke: var(--din-uw-win); stroke-width: 1.8; stroke-dasharray: 5 4; }
  & .marea { fill: color-mix(in oklch, var(--din-uw-win) 10%, transparent); }
  & .reveal { animation: din-uw-wipe 1.2s var(--din-uw-out) .1s backwards; }
  & .mk line { stroke: var(--din-uw-ink); stroke-width: 1.2; }
  & .mk circle { fill: var(--din-uw-accent); stroke: var(--din-uw-bg); stroke-width: 2; }
  & .mk .m2 { fill: var(--din-uw-win); }
  & .mk rect { fill: var(--din-uw-ink); }
  & .mk text { font: 650 10.5px var(--din-uw-mono); fill: var(--din-uw-bg); }
  & .opt path { fill: var(--din-uw-win); stroke: var(--din-uw-bg); stroke-width: 1.5; }
  & .opt text { font: 600 10.5px var(--din-uw-mono); fill: var(--din-uw-win); paint-order: stroke; stroke: var(--din-uw-panel); stroke-width: 4px; }
  & .xh line { stroke: var(--din-uw-mute); stroke-dasharray: 2 2; }
  & .xh { opacity: 0; transition: opacity .15s; pointer-events: none; }
  &.is-hover .xh { opacity: 1; }
}
.din-uw__pctl { flex: none; width: 214px; padding: 14px 14px 14px 4px; display: flex; flex-direction: column; gap: 14px; }
.din-uw__key { list-style: none; display: grid; gap: 4px; font-size: 11.5px; color: var(--din-uw-mute);
  & li { display: flex; align-items: center; gap: 8px; }
  & i { flex: none; width: 16px; height: 0; border-top: 2.4px solid var(--din-uw-accent); border-radius: 2px; }
  & .k2 { border-top: 2px dashed var(--din-uw-win); }
  & .k3 { height: 10px; width: 10px; margin: 0 3px; border: 0; border-top: 2px solid var(--din-uw-wait); background: color-mix(in oklch, var(--din-uw-wait) 18%, transparent); border-radius: 1px; }
}
.din-uw__rate { display: grid; grid-template-columns: 1fr auto; gap: 4px 8px; align-items: baseline;
  & span { font-size: 11.5px; color: var(--din-uw-mute); }
  & output { font: 700 18px var(--din-uw-mono); letter-spacing: -.02em; color: var(--din-uw-accent); }
  & input { grid-column: 1 / -1; width: 100%; margin: 4px 0 0; }
}
.din-uw__read { display: grid; gap: 9px;
  & div { display: grid; gap: 1px; padding-bottom: 8px; border-bottom: 1px solid var(--din-uw-line); }
  & dt { font-size: 11.5px; color: var(--din-uw-mute); }
  & dd { font: 650 15px var(--din-uw-mono); font-variant-numeric: tabular-nums; }
}
.din-uw__opt { padding: 8px 10px; border-radius: 9px; font-weight: 640; font-size: 12.5px; text-align: center; color: var(--din-uw-bg); background: var(--din-uw-win); transition: filter .2s, opacity .2s, transform .3s var(--din-uw-spring);
  &:hover { filter: brightness(1.08); } &:active { transform: scale(.97); }
  &[aria-disabled="true"] { opacity: .45; cursor: default; filter: saturate(.4); }
}

/* ------------------------------------------------------------------ workbench */
.din-uw__work { grid-area: work; min-height: 0; display: flex; flex-direction: column; border-radius: 16px; background: var(--din-uw-panel); box-shadow: inset 0 0 0 1px var(--din-uw-line); overflow: hidden; }
.din-uw__wh { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 10px 12px 6px 14px; flex-wrap: wrap;
  & h3 { font-size: 13.5px; font-weight: 700; letter-spacing: -.01em; } }
.din-uw__wsort { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 12px 9px 14px; font-size: 11.5px; color: var(--din-uw-faint); border-bottom: 1px solid var(--din-uw-line); }
.din-uw__list {
  list-style: none; flex: 1; min-height: 0; overflow: auto; padding: 8px; display: grid; align-content: start; gap: 6px;
  scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--din-uw-ink) 20%, transparent) transparent;
  overscroll-behavior: contain;
}
.din-uw__card {
  position: relative; padding: 9px 10px 9px 12px; border-radius: 11px; background: var(--din-uw-raise); box-shadow: inset 0 0 0 1px var(--din-uw-line);
  display: grid; gap: 4px;
  animation: din-uw-rise .5s var(--din-uw-out) backwards; animation-delay: calc(var(--i) * 30ms);
  &::before { content: ""; position: absolute; left: 0; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--c); }
  &:focus-within { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--din-uw-accent) 60%, transparent); }
  & .t { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; min-width: 0;
    & b { font-weight: 650; font-size: 12.8px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
