    const cards = $$('.' + P + 'card', list), i = cards.indexOf(t.closest('.' + P + 'card'));
    const n = cards[clamp(i + (e.key === 'ArrowDown' ? 1 : -1), 0, cards.length - 1)];
    if (n) n.querySelector('button:last-child').focus(); return;
  }
  if (e.key === 'Escape' && st.focus) { st.focus = null; applyFocus(); }
});

let rz = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => { if (!root.isConnected) return; if (st.tab === 'flow') { cur = null; renderFlow(false); } else renderPrice(false); });
});
ro.observe(fplot); ro.observe(pplot);

renderKpis(agg());
renderFlow(false);
renderList(false);
placeMarker();

css:
.din-renewals {
  /* re-theme with bg, ink, accent (today and selection) and the six status hues */
  --din-renewals-bg: oklch(0.985 0.006 85);
  --din-renewals-ink: oklch(0.23 0.018 60);
  --din-renewals-accent: oklch(0.23 0.018 60);
  --din-renewals-renewed: oklch(0.62 0.12 152);
  --din-renewals-quoted: oklch(0.64 0.1 228);
  --din-renewals-nego: oklch(0.79 0.13 78);
  --din-renewals-open: oklch(0.86 0.012 80);
  --din-renewals-atrisk: oklch(0.6 0.19 30);
  --din-renewals-lapsed: oklch(0.42 0.02 60);

  --din-renewals-card: color-mix(in oklch, var(--din-renewals-bg) 70%, white);
  --din-renewals-line: color-mix(in oklch, var(--din-renewals-ink) 10%, transparent);
  --din-renewals-line2: color-mix(in oklch, var(--din-renewals-ink) 18%, transparent);
  --din-renewals-soft: color-mix(in oklch, var(--din-renewals-ink) 4.5%, transparent);
  --din-renewals-mute: color-mix(in oklch, var(--din-renewals-ink) 62%, var(--din-renewals-bg));
  --din-renewals-faint: color-mix(in oklch, var(--din-renewals-ink) 40%, var(--din-renewals-bg));
  --din-renewals-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --din-renewals-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --din-renewals-out: cubic-bezier(.16, 1, .3, 1);
  --din-renewals-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 17.2%, 1.017 20.9%, 1.043 24.6%, 1.035 30.3%, 1.004 42%, .997 52.3%, 1);

  box-sizing: border-box;
  width: 100%;
  height: var(--din-renewals-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--din-renewals-bg);
  box-shadow: inset 0 0 0 1px var(--din-renewals-line);
  color: var(--din-renewals-ink);
  font: 13px/1.45 var(--din-renewals-sans);
  accent-color: var(--din-renewals-accent);
  color-scheme: light;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ul, ol, dl, dt, dd) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--din-renewals-accent); outline-offset: 2px; }
  & [hidden] { display: none !important; }
}
.din-renewals__wrap { height: 100%; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; padding: 18px 20px 18px; }
.din-renewals__eyebrow { font-size: 11px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--din-renewals-mute); }

/* ------------------------------------------------------------------ header */
.din-renewals__head { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px 20px; flex-wrap: wrap; }
.din-renewals__month { display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
  & h2 { font-size: clamp(26px, 3.6cqi, 40px); font-weight: 300; letter-spacing: -.045em; line-height: 1; text-wrap: balance;
    & span { font: 500 .5em var(--din-renewals-mono); letter-spacing: 0; color: var(--din-renewals-faint); vertical-align: .35em; margin-left: 2px; } }
  & h2.is-in { animation: din-renewals-slide .5s var(--din-renewals-out); }
}
.din-renewals__nav { display: flex; gap: 4px;
  & button { display: grid; place-items: center; height: 30px; min-width: 30px; border-radius: 9px; box-shadow: inset 0 0 0 1px var(--din-renewals-line2); transition: background-color .2s, opacity .2s;
    &:hover { background: var(--din-renewals-soft); }
    &[aria-disabled="true"] { opacity: .35; cursor: default; background: none; }
    & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  }
  & .din-renewals__today { padding: 0 11px; font-size: 12.5px; font-weight: 600; }
}
.din-renewals__chips { display: flex; gap: 6px; flex-wrap: wrap;
  & button { display: inline-flex; align-items: center; gap: 7px; padding: 5px 10px 5px 8px; border-radius: 999px; font-size: 12px; font-weight: 600;
    color: var(--din-renewals-faint); box-shadow: inset 0 0 0 1px var(--din-renewals-line); transition: color .2s, background-color .2s, box-shadow .2s;
    & i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); opacity: .35; transition: opacity .2s, transform .45s var(--din-renewals-spring); }
    & span { font: 600 11px var(--din-renewals-mono); color: var(--din-renewals-faint); }
    &:hover { box-shadow: inset 0 0 0 1px var(--din-renewals-line2); }
    &[aria-pressed="true"] { color: var(--din-renewals-ink); background: var(--din-renewals-card); box-shadow: inset 0 0 0 1px var(--din-renewals-line2), 0 1px 2px var(--din-renewals-line);
      & i { opacity: 1; transform: rotate(45deg) scale(.9); } }
  }
}

/* ------------------------------------------------------------------ KPIs */
.din-renewals__kpis { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0; border-block: 1px solid var(--din-renewals-line); }
.din-renewals__kpi { padding: 9px 14px 10px 0; min-width: 0; display: grid; gap: 1px;
  & + & { padding-left: 14px; border-left: 1px solid var(--din-renewals-line); }
  & p { font-size: 11.5px; font-weight: 550; color: var(--din-renewals-mute); }
  & b { font: 650 clamp(18px, 2.1cqi, 24px)/1.15 var(--din-renewals-sans); letter-spacing: -.035em; font-variant-numeric: tabular-nums;
    animation: din-renewals-rise .7s var(--din-renewals-out) backwards; animation-delay: calc(var(--i) * 55ms + 60ms); }
  & small { font-size: 11px; color: var(--din-renewals-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.din-renewals__kpi--risk b { color: var(--din-renewals-atrisk); }

/* ------------------------------------------------------------------ main */
.din-renewals__main { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) clamp(280px, 29cqi, 336px); gap: 16px; }
.din-renewals__cal { min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.din-renewals__dow { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); padding-bottom: 6px;
  & span { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--din-renewals-faint); padding-left: 8px; }
}
.din-renewals__grid {
  min-height: 0; display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); grid-auto-rows: minmax(0, 1fr);
  border-top: 1px solid var(--din-renewals-line); border-left: 1px solid var(--din-renewals-line);
}
.din-renewals__cell {
  --heat: 0;
  position: relative; min-width: 0; min-height: 0; overflow: hidden;
  border-right: 1px solid var(--din-renewals-line); border-bottom: 1px solid var(--din-renewals-line);
  padding: 6px 7px 6px 8px; display: flex; flex-direction: column; gap: 3px; width: 100%;
  background: color-mix(in oklch, var(--din-renewals-nego) calc(var(--heat) * 26%), var(--din-renewals-card));
  transition: background-color .3s, box-shadow .2s;
  animation: din-renewals-fade .6s var(--din-renewals-out) backwards; animation-delay: calc(var(--i) * 12ms);
  &.is-out { background: transparent; color: var(--din-renewals-faint); cursor: default; }
  &.is-wknd:not(.is-out) { background-image: repeating-linear-gradient(135deg, transparent 0 6px, var(--din-renewals-soft) 6px 7px); }
  &:not(.is-out):hover { box-shadow: inset 0 0 0 1.5px var(--din-renewals-line2); }
  &[aria-selected="true"] { box-shadow: inset 0 0 0 2px var(--din-renewals-accent); z-index: 1; }
  &:focus-visible { outline: none; box-shadow: inset 0 0 0 2px var(--din-renewals-accent); }
  & .top { display: flex; align-items: baseline; justify-content: space-between; gap: 4px; }
  & .d { font: 500 13px var(--din-renewals-sans); font-variant-numeric: tabular-nums; min-width: 22px; height: 22px; display: inline-grid; place-items: center; border-radius: 50%; margin: -2px 0 0 -4px; }
  & .p { font: 600 11px var(--din-renewals-mono); color: var(--din-renewals-ink); white-space: nowrap; }
  & .n { font: 500 10.5px var(--din-renewals-mono); color: var(--din-renewals-faint); }
  & .bar { display: flex; height: 5px; border-radius: 3px; overflow: hidden; gap: 1px; background: var(--din-renewals-soft);
    & i { height: 100%; background: var(--c); transform-origin: 0 50%; animation: din-renewals-bar .7s var(--din-renewals-out) backwards; animation-delay: calc(var(--i) * 12ms + 200ms); }
    & i.dim { opacity: .18; }
  }
  & .nm { font-size: 11px; font-weight: 550; line-height: 1.25; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--din-renewals-mute);
    & em { font-style: normal; display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--c); margin-right: 5px; vertical-align: 1px; } }
  & .more { font-size: 10.5px; color: var(--din-renewals-faint); }
  &.is-today .d { background: var(--din-renewals-accent); color: var(--din-renewals-bg); font-weight: 700; }
  &.is-past:not(.is-out) .d { color: var(--din-renewals-faint); }
}

/* days list: the calendar's narrow form */
.din-renewals__days { display: none; list-style: none; min-height: 0; overflow: auto; scrollbar-width: thin; overscroll-behavior: contain; }
.din-renewals__drow { display: grid; grid-template-columns: 46px minmax(0, 1fr) auto; gap: 4px 12px; align-items: center; width: 100%; padding: 9px 4px 9px 0; border-bottom: 1px solid var(--din-renewals-line);
  & .dd { grid-row: span 2; text-align: center; font: 300 22px/1 var(--din-renewals-sans); letter-spacing: -.04em; & small { display: block; font: 700 9.5px var(--din-renewals-sans); letter-spacing: .1em; text-transform: uppercase; color: var(--din-renewals-faint); margin-top: 3px; } }
  & .nm { font-size: 12.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .p { font: 600 12px var(--din-renewals-mono); text-align: right; }
  & .bar { grid-column: 2 / -1; display: flex; height: 5px; border-radius: 3px; overflow: hidden; gap: 1px; & i { background: var(--c); } & i.dim { opacity: .18; } }
  &[aria-selected="true"] { background: var(--din-renewals-soft); box-shadow: inset 3px 0 0 var(--din-renewals-accent); }
  &.is-today .dd { color: var(--din-renewals-atrisk); }
}

/* ------------------------------------------------------------------ side panel */
.din-renewals__side { min-height: 0; display: grid; border-radius: 16px; background: var(--din-renewals-card); box-shadow: inset 0 0 0 1px var(--din-renewals-line), 0 1px 2px var(--din-renewals-line); overflow: hidden; }
.din-renewals__pane { min-height: 0; display: flex; flex-direction: column; padding: 14px 14px 12px;
  opacity: 1; transform: none; transition: opacity .35s var(--din-renewals-out), transform .45s var(--din-renewals-out);
  @starting-style { opacity: 0; transform: translateX(14px); }
}
.din-renewals__ph { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; margin-bottom: 8px;
  & h3 { font-size: 15px; font-weight: 700; letter-spacing: -.015em; }
}
.din-renewals__seg { display: inline-flex; padding: 2px; border-radius: 8px; background: var(--din-renewals-soft); box-shadow: inset 0 0 0 1px var(--din-renewals-line);
  & button { min-width: 28px; padding: 3px 8px; border-radius: 6px; font: 600 12px var(--din-renewals-mono); text-align: center; color: var(--din-renewals-mute);
    &[aria-checked="true"] { background: var(--din-renewals-card); color: var(--din-renewals-ink); box-shadow: 0 1px 2px var(--din-renewals-line2); } }
}
.din-renewals__chart { position: relative; height: 168px; flex: none;
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; touch-action: pan-y; }
  & .gl { stroke: var(--din-renewals-line); }
  & .tx { font: 500 10px var(--din-renewals-mono); fill: var(--din-renewals-faint); font-variant-numeric: tabular-nums; }
  & .exp { fill: none; stroke: var(--din-renewals-ink); stroke-width: 1.4; stroke-dasharray: 1 3; stroke-linecap: round; }
  & .sec { fill: color-mix(in oklch, var(--din-renewals-renewed) 22%, transparent); stroke: var(--din-renewals-renewed); stroke-width: 2; stroke-linejoin: round; }
  & .pro { fill: none; stroke: var(--din-renewals-quoted); stroke-width: 1.6; stroke-dasharray: 5 3; }
  & .todayl { stroke: var(--din-renewals-atrisk); stroke-width: 1; }
  & .todayt { font: 700 9.5px var(--din-renewals-sans); letter-spacing: .08em; fill: var(--din-renewals-atrisk); }
  & .reveal { animation: din-renewals-wipe 1.1s var(--din-renewals-out) .1s backwards; }
  & .xh { opacity: 0; transition: opacity .15s; pointer-events: none; & line { stroke: var(--din-renewals-mute); stroke-dasharray: 2 2; } & circle { stroke: var(--din-renewals-card); stroke-width: 2; } }
  & svg.is-hover .xh { opacity: 1; }
}
.din-renewals__tip { position: absolute; top: 0; left: 0; z-index: 3; pointer-events: none; min-width: 150px; padding: 8px 10px; border-radius: 10px; background: var(--din-renewals-ink); color: var(--din-renewals-bg); font-size: 11.5px; box-shadow: 0 12px 28px -12px var(--din-renewals-ink);
  & b { display: block; margin-bottom: 2px; }
  & p { display: flex; justify-content: space-between; gap: 12px; & span { font-family: var(--din-renewals-mono); } }
}
.din-renewals__key { list-style: none; display: flex; gap: 12px; padding: 6px 0 10px; font-size: 11px; color: var(--din-renewals-mute); border-bottom: 1px solid var(--din-renewals-line);
  & li { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 14px; height: 0; border-top: 2px solid; }
  & .k-exp { border-top: 2px dotted var(--din-renewals-ink); } & .k-sec { border-color: var(--din-renewals-renewed); } & .k-pro { border-top: 2px dashed var(--din-renewals-quoted); }
}
.din-renewals__sub { font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--din-renewals-faint); padding: 10px 0 4px; }
.din-renewals__plist { list-style: none; flex: 1; min-height: 0; overflow: auto; margin: 0 -6px; padding: 0 6px 4px; scrollbar-width: thin; overscroll-behavior: contain; }
.din-renewals__pi {
  display: grid; grid-template-columns: 8px minmax(0, 1fr) auto; gap: 1px 10px; align-items: center; width: 100%; padding: 8px 8px; border-radius: 10px;
  transition: background-color .2s;
  animation: din-renewals-rise .45s var(--din-renewals-out) backwards; animation-delay: calc(var(--i) * 35ms);
  &:hover { background: var(--din-renewals-soft); }
  & > i { grid-row: span 2; width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  & b { font-size: 12.5px; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .p { font: 600 12px var(--din-renewals-mono); text-align: right; }
  & small { font-size: 11px; color: var(--din-renewals-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .s { font-size: 10.5px; font-weight: 650; text-align: right; color: var(--sc, var(--din-renewals-mute)); white-space: nowrap; }
}
.din-renewals__empty { padding: 30px 8px; text-align: center; color: var(--din-renewals-faint); font-size: 12px; text-wrap: balance; }
.din-renewals__back { display: inline-flex; align-items: center; gap: 3px; padding: 4px 9px 4px 5px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--din-renewals-mute); box-shadow: inset 0 0 0 1px var(--din-renewals-line);
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { color: var(--din-renewals-ink); background: var(--din-renewals-soft); }
}
.din-renewals__dsum { font: 600 11.5px var(--din-renewals-mono); color: var(--din-renewals-mute); text-align: right; }
.din-renewals__dtitle { font-size: 20px; font-weight: 300; letter-spacing: -.035em; margin: 2px 0 6px; text-wrap: balance; }
.din-renewals__pill { display: inline-flex; align-items: center; gap: 6px; padding: 3px 9px 3px 7px; border-radius: 999px; font-size: 11.5px; font-weight: 650; background: color-mix(in oklch, var(--c) 16%, transparent); color: color-mix(in oklch, var(--c) 70%, var(--din-renewals-ink));
  &::before { content: ""; width: 7px; height: 7px; border-radius: 2px; background: var(--c); }
  &.is-pop { animation: din-renewals-pop .55s var(--din-renewals-spring); }
}

.din-renewals__pol { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; display: flex; flex-direction: column; gap: 12px;
  & h3 { font-size: 18px; font-weight: 680; letter-spacing: -.025em; line-height: 1.2; text-wrap: balance; }
  & .ref { font: 500 11px var(--din-renewals-mono); color: var(--din-renewals-faint); margin-top: 2px; }
  & dl { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 12px; padding: 10px 0; border-block: 1px solid var(--din-renewals-line);
    & dt { font-size: 10.5px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--din-renewals-faint); }
    & dd { font-size: 12.5px; font-weight: 600; font-variant-numeric: tabular-nums; }
    & dd.m { font-family: var(--din-renewals-mono); }
  }
  & .steps { list-style: none; display: grid; gap: 0; }
  & .steps li { position: relative; display: grid; grid-template-columns: 18px 1fr auto; gap: 8px; align-items: center; padding: 4px 0; font-size: 12px; color: var(--din-renewals-faint);
    &::before { content: ""; width: 9px; height: 9px; margin-left: 4px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px currentColor; }
    &:not(:last-child)::after { content: ""; position: absolute; left: 8px; top: 18px; height: calc(100% - 10px); width: 1px; background: var(--din-renewals-line2); }
    & time { font: 500 10.5px var(--din-renewals-mono); }
    &.done { color: var(--din-renewals-ink); &::before { background: var(--din-renewals-renewed); box-shadow: none; } }
    &.now { color: var(--din-renewals-ink); font-weight: 650; &::before { background: var(--din-renewals-bg); box-shadow: inset 0 0 0 2.5px var(--c); } }
  }
  & .acts { display: flex; flex-wrap: wrap; gap: 6px; margin-top: auto; padding-top: 4px; }
  & .acts button { padding: 7px 11px; border-radius: 9px; font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--din-renewals-line2); transition: background-color .2s, transform .3s var(--din-renewals-spring);
    &:hover { background: var(--din-renewals-soft); } &:active { transform: scale(.96); }
    &.pri { background: var(--din-renewals-ink); color: var(--din-renewals-bg); box-shadow: none; &:hover { background: color-mix(in oklch, var(--din-renewals-ink) 85%, var(--din-renewals-bg)); } }
    &[aria-disabled="true"] { opacity: .4; cursor: default; background: none; }
  }
  & .note { font-size: 12px; color: var(--din-renewals-mute); text-wrap: pretty; }
}
.din-renewals__toast { position: absolute; right: 20px; bottom: 18px; z-index: 10; max-width: min(340px, calc(100% - 40px)); padding: 10px 14px; border-radius: 12px; background: var(--din-renewals-ink); color: var(--din-renewals-bg); font-size: 12.5px; font-weight: 550; box-shadow: 0 16px 34px -14px var(--din-renewals-ink);
  transition: opacity .3s, transform .45s var(--din-renewals-spring);
  @starting-style { opacity: 0; transform: translateY(12px); }
}

@keyframes din-renewals-rise { from { opacity: 0; transform: translateY(6px); } }
@keyframes din-renewals-fade { from { opacity: 0; } }
@keyframes din-renewals-bar { from { transform: scaleX(0); } }
@keyframes din-renewals-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes din-renewals-slide { from { opacity: 0; transform: translateX(var(--dx, 16px)); } }
@keyframes din-renewals-pop { 0% { transform: scale(.8); } }

/* ------------------------------------------------------------------ responsive */
@container (max-width: 1000px) {
  .din-renewals__cell .nm2 { display: none; }
}
@container (max-width: 860px) {
  .din-renewals__kpi:nth-child(4) { display: none; }
  .din-renewals__kpis { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@container (max-width: 760px) {
  .din-renewals__main { display: flex; flex-direction: column; gap: 14px; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; margin-right: -8px; padding-right: 8px; }
  .din-renewals__cal { flex: none; grid-template-rows: auto auto; }
  .din-renewals__side { flex: none; }
  .din-renewals__grid { grid-auto-rows: 64px; }
  .din-renewals__cell .nm2, .din-renewals__cell .more { display: none; }
  .din-renewals__side { overflow: visible; }
  .din-renewals__plist { flex: none; max-height: none; overflow: visible; }
}
@container (max-width: 600px) {
