  if (p.s === 'open') { acts = B('terms', 'Send terms ' + sgn(p.rate), true) + B('risk', 'Flag at risk'); note = 'Invitation ' + (p.t - 60 * DAY < TODAY ? 'overdue since ' + dstr(p.t - 60 * DAY) : 'due ' + dstr(p.t - 60 * DAY)) + '. Expiring terms roll at ' + sgn(p.rate) + ' on the rating guide.'; }
  else if (p.s === 'nego') { acts = B('terms', 'Send terms ' + sgn(p.rate), true) + B('risk', 'Flag at risk'); note = p.broker + ' asked for a deductible option; underwriting has cleared ' + sgn(p.rate) + '.'; }
  else if (p.s === 'quoted') { acts = B('renew', 'Mark renewed', true) + B('chase', p.chased ? 'Chased ' + p.chased + '×' : 'Chase broker'); note = 'Terms sent at ' + sgn(p.rate) + ', ' + eurL(newP) + '. Awaiting the broker’s instruction.'; }
  else if (p.s === 'atrisk') { acts = B('match', 'Requote at ' + sgn(Math.max(0, p.rate - p.comp)), true) + B('lapse', 'Mark lapsed') + B('chase', p.chased ? 'Chased ' + p.chased + '×' : 'Chase broker'); note = 'Broker is marketing the risk; a competing quote came in about ' + Math.round(p.comp * 100) + '% below our terms.'; }
  else if (p.s === 'renewed') { acts = B('docs', p.docs ? 'Documents issued' : 'Issue documents', true, p.docs ? 'Renewal documents already issued to ' + p.broker : ''); note = 'Renewed at ' + sgn(p.rate) + ': ' + eurL(p.prem) + ' to ' + eurL(newP) + '.'; }
  else { acts = B('reopen', 'Requote', true, p.t < TODAY ? 'Cover lapsed on ' + dstr(p.t) + '; a new submission is needed' : ''); note = 'Lapsed. ' + p.broker + ' placed the risk elsewhere.'; }
  $('[data-pdetail]').innerHTML =
    '<div><h3>' + p.name + '</h3><p class="ref">' + p.ref + ' · ' + p.line + '</p></div>' +
    '<dl><div><dt>Expiring premium</dt><dd class="m">' + eurL(p.prem) + '</dd></div><div><dt>Renews</dt><dd>' + dstr(p.t) + ' · ' + when + '</dd></div>' +
    '<div><dt>Broker</dt><dd>' + p.broker + '</dd></div><div><dt>Handler</dt><dd>' + p.handler + '</dd></div></dl>' +
    '<ol class="steps" style="--c:' + S.c + '">' + STEPS.map((s, i) => { let t = p.t + s[1] * DAY; if (i < done && t > TODAY) t = TODAY - (done - i) * 2 * DAY; return '<li class="' + (i < done ? 'done' : i === done && p.s !== 'lapsed' ? 'now' : '') + '">' + s[0] + '<time>' + dstr(t) + '</time></li>'; }).join('') + '</ol>' +
    '<p class="note">' + note + '</p><div class="acts">' + acts + '</div>';
}
function setPane(k) {
