}

/* ------------------------------------------------------------------ actions */
const toast = $('[data-toast]'); let toastT = 0;
function say(msg) { toast.textContent = msg; toast.hidden = false; clearTimeout(toastT); toastT = setTimeout(() => { toast.hidden = true; }, 3200); }
function act(k) {
