  if (k === 'terms') { p.s = 'quoted'; say('Renewal terms sent to ' + p.broker + ' for ' + p.name); }
  else if (k === 'risk') { p.s = 'atrisk'; say(p.name + ' flagged at risk'); }
  else if (k === 'renew') { p.s = 'renewed'; say(p.name + ' renewed at ' + sgn(p.rate) + ', ' + eurL(p.prem * (1 + p.rate))); }
  else if (k === 'match') { p.rate = Math.max(0, Math.round((p.rate - p.comp) * 1000) / 1000); p.s = 'quoted'; say('Requoted ' + p.name + ' at ' + sgn(p.rate)); }
  else if (k === 'lapse') { p.s = 'lapsed'; say(p.name + ' marked lapsed'); }
  else if (k === 'chase') { p.chased++; say('Reminder sent to ' + p.broker); }
  else if (k === 'docs') { p.docs = true; say('Renewal documents issued to ' + p.broker); }
  else if (k === 'reopen') { p.s = 'quoted'; say('Requote sent for ' + p.name); }
  refresh(false);
