  renderHead(dir); renderKpis(); renderCal(true); setPane('month'); renderChart(true); renderTop();
}

root.addEventListener('click', (e) => {
  const b = e.target.closest('button');
  if (!b || !root.contains(b)) return;
  if (b.getAttribute('aria-disabled') === 'true') return;
  if (b.matches('[data-step]')) { goMonth(st.mi + +b.dataset.step, +b.dataset.step); return; }
  if (b.matches('[data-today]')) { if (st.mi !== 1) goMonth(1, 1); selectDay(2); return; }
  if (b.matches('[data-stat]')) {
    const k = b.dataset.stat;
    if (st.show.has(k) && st.show.size === 1) ORDER.forEach((x) => st.show.add(x)); else if (st.show.has(k)) st.show.delete(k); else st.show.add(k);
