@property --din-fraud-pct { syntax: "<number>"; inherits: false; initial-value: 0; }

.din-fraud {
  /* re-theme with bg, ink, accent (high scores, alarms) and the five entity hues */
  --din-fraud-bg: oklch(0.185 0.012 45);
  --din-fraud-ink: oklch(0.94 0.012 75);
  --din-fraud-accent: oklch(0.69 0.18 36);
  --din-fraud-mid: oklch(0.8 0.13 68);
  --din-fraud-ok: oklch(0.78 0.09 170);
  --din-fraud-phone: oklch(0.86 0.12 102);
  --din-fraud-bank: oklch(0.78 0.09 168);
  --din-fraud-addr: oklch(0.76 0.08 240);
  --din-fraud-shop: oklch(0.74 0.13 350);
  --din-fraud-person: oklch(0.87 0.03 75);

  --din-fraud-panel: color-mix(in oklch, var(--din-fraud-bg) 93%, var(--din-fraud-ink));
  --din-fraud-raise: color-mix(in oklch, var(--din-fraud-bg) 86%, var(--din-fraud-ink));
  --din-fraud-line: color-mix(in oklch, var(--din-fraud-ink) 10%, transparent);
  --din-fraud-soft: color-mix(in oklch, var(--din-fraud-ink) 6%, transparent);
  --din-fraud-mute: color-mix(in oklch, var(--din-fraud-ink) 62%, var(--din-fraud-bg));
  --din-fraud-faint: color-mix(in oklch, var(--din-fraud-ink) 36%, var(--din-fraud-bg));
  --din-fraud-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --din-fraud-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --din-fraud-out: cubic-bezier(.16, 1, .3, 1);
  --din-fraud-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 17.2%, 1.017 20.9%, 1.043 24.6%, 1.035 30.3%, 1.004 42%, .997 52.3%, 1);

  box-sizing: border-box;
  width: 100%;
  height: var(--din-fraud-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  display: grid; grid-template-rows: auto minmax(0, 1fr);
  border-radius: 18px;
  background: var(--din-fraud-bg);
  color: var(--din-fraud-ink);
  font: 13px/1.45 var(--din-fraud-sans);
  accent-color: var(--din-fraud-accent);
  color-scheme: dark;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ul, ol, dl, dt, dd) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--din-fraud-accent); outline-offset: 2px; }
  & [hidden] { display: none !important; }
}
.din-fraud__eyebrow { font-size: 11px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--din-fraud-mute); }

/* ------------------------------------------------------------------ header */
.din-fraud__head { display: flex; align-items: center; justify-content: space-between; gap: 10px 20px; flex-wrap: wrap; padding: 14px 18px 12px; border-bottom: 1px solid var(--din-fraud-line); }
.din-fraud__brand { display: flex; align-items: center; gap: 12px;
  & svg { width: 36px; height: 36px; flex: none; padding: 7px; border-radius: 10px; background: var(--din-fraud-accent); fill: none; stroke: var(--din-fraud-bg); stroke-width: 2.1; stroke-linecap: round; }
  & h2 { font-size: clamp(17px, 2cqi, 22px); font-weight: 720; letter-spacing: -.03em; line-height: 1.1; text-wrap: balance; }
}
.din-fraud__stats { display: flex; gap: 4px 22px; flex-wrap: wrap;
  & div { display: grid; }
  & dt { font-size: 11px; color: var(--din-fraud-mute); }
  & dd { font: 680 18px/1.15 var(--din-fraud-mono); letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & dd.is-bump { animation: din-fraud-bump .5s var(--din-fraud-spring); }
}

/* ------------------------------------------------------------------ layout */
.din-fraud__main { min-height: 0; display: grid; grid-template-columns: clamp(250px, 25cqi, 290px) minmax(0, 1fr) clamp(272px, 27cqi, 312px); grid-template-areas: "queue graph case"; }
.din-fraud__queue { grid-area: queue; min-height: 0; display: flex; flex-direction: column; border-right: 1px solid var(--din-fraud-line); }
.din-fraud__graph { grid-area: graph; min-width: 0; min-height: 0; display: flex; flex-direction: column; background: radial-gradient(70% 60% at 50% 50%, color-mix(in oklch, var(--din-fraud-ink) 4%, transparent), transparent 70%); }
.din-fraud__case { grid-area: case; min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--din-fraud-line) transparent; border-left: 1px solid var(--din-fraud-line); padding: 14px 16px 16px; display: flex; flex-direction: column; gap: 12px; }

/* ------------------------------------------------------------------ queue */
.din-fraud__qh { padding: 8px 10px 8px 12px; display: grid; gap: 8px; border-bottom: 1px solid var(--din-fraud-line); }
.din-fraud__tabs { display: flex; gap: 2px;
  & button { flex: 1; padding: 6px 4px; border-radius: 8px; font-size: 12px; font-weight: 620; color: var(--din-fraud-mute); text-align: center; white-space: nowrap; transition: background-color .2s, color .2s;
    & span { font: 600 11px var(--din-fraud-mono); opacity: .8; }
    &:hover { color: var(--din-fraud-ink); }
    &[aria-selected="true"] { background: var(--din-fraud-raise); color: var(--din-fraud-ink); box-shadow: inset 0 0 0 1px var(--din-fraud-line); }
  }
}
.din-fraud__sort { display: flex; align-items: center; justify-content: space-between; font-size: 11px; color: var(--din-fraud-faint); }
.din-fraud__seg { display: inline-flex; padding: 2px; border-radius: 8px; background: var(--din-fraud-soft); box-shadow: inset 0 0 0 1px var(--din-fraud-line);
  & button { padding: 3px 9px; border-radius: 6px; font-size: 11.5px; font-weight: 620; color: var(--din-fraud-mute); white-space: nowrap; transition: background-color .2s, color .2s;
    &:hover { color: var(--din-fraud-ink); }
    &[aria-checked="true"] { background: var(--din-fraud-ink); color: var(--din-fraud-bg); } }
}
.din-fraud__list { list-style: none; flex: 1; min-height: 0; overflow: auto; padding: 6px; scrollbar-width: thin; scrollbar-color: var(--din-fraud-line) transparent; overscroll-behavior: contain; outline: none; }
.din-fraud__opt {
  position: relative; display: grid; grid-template-columns: 38px minmax(0, 1fr) auto; gap: 0 10px; align-items: center; padding: 8px 8px; border-radius: 10px; cursor: pointer;
  transition: background-color .2s;
  animation: din-fraud-rise .45s var(--din-fraud-out) backwards; animation-delay: calc(var(--i) * 28ms);
  &:hover { background: var(--din-fraud-soft); }
  &[aria-selected="true"] { background: var(--din-fraud-raise); box-shadow: inset 0 0 0 1px var(--din-fraud-line); &::before { content: ""; position: absolute; left: -6px; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--sc); } }
  &:focus-visible { outline-offset: -2px; }
  & .sc { grid-row: span 2; display: grid; place-items: center; height: 38px; border-radius: 9px; font: 700 15px var(--din-fraud-mono); color: var(--sc); background: color-mix(in oklch, var(--sc) 13%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--sc) 30%, transparent); }
  & b { font: 650 12px var(--din-fraud-mono); letter-spacing: -.01em; }
  & .am { font: 600 12px var(--din-fraud-mono); text-align: right; }
  & small { grid-column: 2 / -1; font-size: 11.5px; color: var(--din-fraud-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.din-fraud__empty { padding: 30px 14px; text-align: center; color: var(--din-fraud-faint); font-size: 12px; text-wrap: balance; }
.din-fraud__keys { padding: 7px 12px 9px; font-size: 11px; color: var(--din-fraud-faint); border-top: 1px solid var(--din-fraud-line);
  & kbd { font: 600 10px var(--din-fraud-mono); padding: 1px 5px; border-radius: 4px; box-shadow: inset 0 0 0 1px var(--din-fraud-line), 0 1px 0 var(--din-fraud-line); margin-right: 2px; }
}

/* ------------------------------------------------------------------ graph */
.din-fraud__gbar { display: flex; align-items: center; gap: 10px; padding: 9px 12px; }
.din-fraud__gtitle { flex: 1; min-width: 0; font-size: 12px; color: var(--din-fraud-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; & b { color: var(--din-fraud-ink); font-family: var(--din-fraud-mono); } }
.din-fraud__backbtn { display: inline-flex; align-items: center; gap: 4px; padding: 4px 9px 4px 5px; border-radius: 8px; font: 600 11.5px var(--din-fraud-mono); color: var(--din-fraud-mute); box-shadow: inset 0 0 0 1px var(--din-fraud-line);
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { color: var(--din-fraud-ink); background: var(--din-fraud-soft); }
}
.din-fraud__gplot { position: relative; flex: 1; min-height: 0; }
.din-fraud__svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible;
  & text { font-family: var(--din-fraud-sans); }
  & .ring { fill: none; stroke: var(--din-fraud-line); stroke-dasharray: 2 5; }
  & .e { fill: none; stroke-linecap: round; transition: opacity .25s, stroke-width .25s; }
  & .e1 { stroke: var(--c); stroke-width: 1.6; opacity: .65; }
  & .e2 { stroke: var(--din-fraud-ink); stroke-width: 1; opacity: .26; }
  & .e2.closed { stroke-dasharray: 3 3; }
  & .draw { stroke-dasharray: 1 1; animation: din-fraud-draw .8s var(--din-fraud-out) backwards; animation-delay: calc(var(--i) * 30ms + 120ms); }
  & .n { cursor: pointer; outline: none; transition: opacity .25s; }
  & .n .pop { transform-box: fill-box; transform-origin: 50% 50%; animation: din-fraud-pop .6s var(--din-fraud-spring) backwards; animation-delay: calc(var(--i) * 30ms); }
  & .n .halo { fill: none; stroke: var(--din-fraud-ink); stroke-width: 1.5; opacity: 0; transition: opacity .2s; }
  & .n:hover .halo, & .n:focus-visible .halo, & .n[aria-pressed="true"] .halo { opacity: .9; }
  & .n:focus-visible .halo { stroke-dasharray: 3 3; }
  & .ent .disc { fill: color-mix(in oklch, var(--c) 18%, var(--din-fraud-bg)); stroke: var(--c); stroke-width: 1.5; }
  & .ent .ic { fill: none; stroke: var(--c); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & .ent .watch { fill: var(--din-fraud-accent); stroke: var(--din-fraud-bg); stroke-width: 2; }
  & .ent text { font-size: 10.5px; font-weight: 600; fill: var(--din-fraud-mute); paint-order: stroke; stroke: var(--din-fraud-bg); stroke-width: 4px; stroke-linejoin: round; }
  & .clm .disc { fill: var(--din-fraud-bg); stroke: var(--sc); stroke-width: 2; }
  & .clm.closed .disc { stroke-dasharray: 2.5 2; }
  & .clm .dot { fill: var(--sc); }
  & .clm text { font: 600 10px var(--din-fraud-mono); fill: var(--din-fraud-mute); paint-order: stroke; stroke: var(--din-fraud-bg); stroke-width: 4px; stroke-linejoin: round; }
  & .ctr { cursor: default; }
  & .ctr .disc { fill: var(--din-fraud-panel); stroke: var(--din-fraud-line); stroke-width: 1; }
  & .ctr .arc { fill: none; stroke: var(--sc); stroke-width: 5; stroke-linecap: round; }
  & .ctr .s1 { font: 750 22px var(--din-fraud-mono); fill: var(--din-fraud-ink); letter-spacing: -.04em; }
  & .ctr .s2 { font: 600 9.5px var(--din-fraud-sans); letter-spacing: .1em; fill: var(--din-fraud-faint); }
  & .ctr .s3 { font: 650 11.5px var(--din-fraud-mono); fill: var(--din-fraud-ink); paint-order: stroke; stroke: var(--din-fraud-bg); stroke-width: 4px; }
  &.is-hl .e:not(.hl) { opacity: .07; }
  &.is-hl .n:not(.hl):not(.ctr) { opacity: .3; }
  &.is-hl .e.hl { opacity: .95; stroke-width: 2.2; }
}
.din-fraud__tip { position: absolute; left: 0; top: 0; z-index: 4; pointer-events: none; max-width: 230px; padding: 8px 10px; border-radius: 10px; font-size: 11.5px; color: var(--din-fraud-mute);
  background: color-mix(in oklch, var(--din-fraud-bg) 70%, black); box-shadow: 0 0 0 1px var(--din-fraud-line), 0 14px 30px -12px black;
  & b { display: block; color: var(--din-fraud-ink); font-weight: 650; }
}
.din-fraud__ecard { position: absolute; left: 12px; bottom: 12px; z-index: 5; width: min(280px, calc(100% - 24px)); padding: 12px; border-radius: 13px;
  background: color-mix(in oklch, var(--din-fraud-bg) 80%, black); box-shadow: 0 0 0 1px var(--din-fraud-line), 0 20px 44px -16px black;
  transition: opacity .25s, transform .4s var(--din-fraud-spring);
  @starting-style { opacity: 0; transform: translateY(10px) scale(.98); }
  & .h { display: flex; align-items: flex-start; gap: 10px; }
  & .h svg { width: 30px; height: 30px; flex: none; padding: 6px; border-radius: 8px; background: color-mix(in oklch, var(--c) 18%, transparent); fill: none; stroke: var(--c); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & .h div { flex: 1; min-width: 0; }
  & .h p { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--din-fraud-faint); }
  & .h b { display: block; font-size: 13px; font-weight: 650; overflow-wrap: anywhere; }
  & .x { width: 24px; height: 24px; display: grid; place-items: center; border-radius: 6px; color: var(--din-fraud-mute); & svg { width: 14px; height: 14px; padding: 0; background: none; stroke: currentColor; stroke-width: 1.8; } &:hover { background: var(--din-fraud-soft); color: var(--din-fraud-ink); } }
