.din-cat {
  /* re-theme with sea, land, ink and the storm hue (wind ramp is drawn from it in JS) */
  --din-cat-sea: oklch(0.235 0.028 222);
  --din-cat-land: oklch(0.33 0.026 78);
  --din-cat-ink: oklch(0.95 0.012 85);
  --din-cat-storm: oklch(0.66 0.22 18);
  --din-cat-warn: oklch(0.8 0.15 70);

  --din-cat-panel: color-mix(in oklch, var(--din-cat-sea) 70%, black);
  --din-cat-coast: color-mix(in oklch, var(--din-cat-land) 55%, var(--din-cat-ink));
  --din-cat-line: color-mix(in oklch, var(--din-cat-ink) 11%, transparent);
  --din-cat-soft: color-mix(in oklch, var(--din-cat-ink) 6%, transparent);
  --din-cat-mute: color-mix(in oklch, var(--din-cat-ink) 62%, var(--din-cat-sea));
  --din-cat-faint: color-mix(in oklch, var(--din-cat-ink) 38%, var(--din-cat-sea));
  --din-cat-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --din-cat-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --din-cat-out: cubic-bezier(.16, 1, .3, 1);
  --din-cat-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 17.2%, 1.017 20.9%, 1.043 24.6%, 1.035 30.3%, 1.004 42%, .997 52.3%, 1);

  box-sizing: border-box;
  width: 100%;
  height: var(--din-cat-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--din-cat-panel);
  color: var(--din-cat-ink);
  font: 13px/1.45 var(--din-cat-sans);
  accent-color: var(--din-cat-storm);
  color-scheme: dark;
  & *, & *::before, & *::after { box-sizing: border-box; }
