.din-reserves {
  /* re-theme with paper, ink, accent (red-ink exclusions), mark (the highlighter) and ibnr */
  --din-reserves-bg: oklch(0.985 0.008 95);
  --din-reserves-ink: oklch(0.27 0.025 260);
  --din-reserves-accent: oklch(0.53 0.17 27);
  --din-reserves-mark: oklch(0.93 0.12 102);
  --din-reserves-ibnr: oklch(0.6 0.1 200);

  --din-reserves-card: color-mix(in oklch, var(--din-reserves-bg) 55%, white);
  --din-reserves-rule: color-mix(in oklch, var(--din-reserves-ink) 10%, transparent);
  --din-reserves-rule2: color-mix(in oklch, var(--din-reserves-ink) 20%, transparent);
  --din-reserves-soft: color-mix(in oklch, var(--din-reserves-ink) 4.5%, transparent);
  --din-reserves-mute: color-mix(in oklch, var(--din-reserves-ink) 62%, var(--din-reserves-bg));
  --din-reserves-faint: color-mix(in oklch, var(--din-reserves-ink) 40%, var(--din-reserves-bg));
  --din-reserves-case: color-mix(in oklch, var(--din-reserves-ink) 38%, var(--din-reserves-bg));
  --din-reserves-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --din-reserves-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --din-reserves-out: cubic-bezier(.16, 1, .3, 1);
  --din-reserves-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 17.2%, 1.017 20.9%, 1.043 24.6%, 1.035 30.3%, 1.004 42%, .997 52.3%, 1);

  box-sizing: border-box;
  width: 100%;
  height: var(--din-reserves-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background:
    repeating-linear-gradient(transparent 0 25px, color-mix(in oklch, var(--din-reserves-ibnr) 6%, transparent) 25px 26px),
    var(--din-reserves-bg);
  box-shadow: inset 0 0 0 1px var(--din-reserves-rule);
  color: var(--din-reserves-ink);
  font: 13px/1.45 var(--din-reserves-sans);
  accent-color: var(--din-reserves-accent);
  color-scheme: light;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, ol, dl, dt, dd) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--din-reserves-ink); outline-offset: 2px; }
  & [hidden] { display: none !important; }
}
.din-reserves__wrap { height: 100%; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 14px; padding: 18px 20px 18px; }
.din-reserves__eyebrow { font-size: 11px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--din-reserves-mute); }

/* ------------------------------------------------------------------ header */
.din-reserves__head { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px 18px; flex-wrap: wrap;
  & h2 { font-size: clamp(20px, 2.6cqi, 28px); font-weight: 760; letter-spacing: -.04em; line-height: 1.1; text-wrap: balance;
