}
.din-reserves__ctl { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.din-reserves__seg { display: inline-flex; padding: 2px; border-radius: 9px; box-shadow: inset 0 0 0 1px var(--din-reserves-rule2); background: var(--din-reserves-card);
