.din-reserves__tail { display: inline-flex; align-items: center; gap: 2px; padding: 2px 2px 2px 10px; border-radius: 9px; box-shadow: inset 0 0 0 1px var(--din-reserves-rule2); background: var(--din-reserves-card);
  & span { font-size: 12px; font-weight: 600; color: var(--din-reserves-mute); margin-right: 4px; }
  & output { min-width: 46px; text-align: center; font: 650 12.5px var(--din-reserves-mono); font-variant-numeric: tabular-nums; }
  & output.is-tick { animation: din-reserves-tick .4s var(--din-reserves-spring); }
  & button { width: 26px; height: 26px; border-radius: 7px; font-size: 15px; font-weight: 600; text-align: center; color: var(--din-reserves-mute);
