/* ------------------------------------------------------------------ KPIs: a ruled ledger line */
.din-reserves__kpis { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); border-block: 1.5px solid var(--din-reserves-ink);
  & div { padding: 8px 12px 9px; min-width: 0; animation: din-reserves-rise .6s var(--din-reserves-out) backwards; animation-delay: calc(var(--i) * 55ms); }
  & div + div { border-left: 1px solid var(--din-reserves-rule); }
  & dt { font-size: 11px; font-weight: 600; letter-spacing: .02em; color: var(--din-reserves-mute); }
  & dd { font: 700 clamp(17px, 2cqi, 22px)/1.2 var(--din-reserves-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
  & small { display: block; font-size: 10.5px; color: var(--din-reserves-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .is-ibnr dd { color: color-mix(in oklch, var(--din-reserves-ibnr) 70%, var(--din-reserves-ink)); }
  & .is-gap dd.up { color: var(--din-reserves-accent); }
  & .is-gap dd.dn { color: color-mix(in oklch, var(--din-reserves-ibnr) 75%, var(--din-reserves-ink)); }
}

/* ------------------------------------------------------------------ main */
.din-reserves__main { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) clamp(272px, 29cqi, 330px); gap: 18px; }
.din-reserves__tri { position: relative; min-width: 0; min-height: 0; display: flex; flex-direction: column; }
.din-reserves__tbar { display: flex; align-items: center; gap: 8px 14px; flex-wrap: wrap; margin-bottom: 8px; }
.din-reserves__tabs { display: flex; gap: 14px;
  & button { position: relative; padding: 2px 0 6px; font-size: 13px; font-weight: 650; color: var(--din-reserves-faint); transition: color .2s;
    &::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: var(--din-reserves-ink); transform: scaleX(0); transform-origin: 0 50%; transition: transform .45s var(--din-reserves-out); }
    &:hover { color: var(--din-reserves-ink); }
    &[aria-selected="true"] { color: var(--din-reserves-ink); &::after { transform: none; } } }
}
.din-reserves__hint { flex: 1; min-width: 160px; font-size: 11.5px; color: var(--din-reserves-faint); text-wrap: pretty; }
.din-reserves__reset { padding: 4px 9px; border-radius: 7px; font-size: 11.5px; font-weight: 650; color: var(--din-reserves-accent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--din-reserves-accent) 35%, transparent);
  &:hover { background: color-mix(in oklch, var(--din-reserves-accent) 8%, transparent); } }
.din-reserves__scroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; overscroll-behavior: contain; border-top: 1.5px solid var(--din-reserves-ink); }
.din-reserves__grid { display: grid; grid-template-columns: 52px repeat(var(--cols), minmax(52px, 1fr)); grid-auto-rows: minmax(25px, 1fr); min-height: 100%; min-width: max-content; width: 100%; font: 500 11.5px var(--din-reserves-mono); font-variant-numeric: tabular-nums; }
.din-reserves__grid > [role="row"] { display: contents; }
.din-reserves__h, .din-reserves__ay, .din-reserves__c {
  min-height: 25px; display: flex; align-items: center; justify-content: flex-end; padding: 0 7px; border-bottom: 1px solid var(--din-reserves-rule); white-space: nowrap; }
.din-reserves__h { position: sticky; top: 0; z-index: 2; background: var(--din-reserves-bg); font: 650 10.5px var(--din-reserves-sans); letter-spacing: .04em; color: var(--din-reserves-mute); border-bottom: 1px solid var(--din-reserves-rule2);
  &.is-x { color: var(--din-reserves-ink); background: color-mix(in oklch, var(--din-reserves-mark) 50%, var(--din-reserves-bg)); } }
.din-reserves__h:first-child { justify-content: flex-start; }
.din-reserves__ay { position: sticky; left: 0; z-index: 1; justify-content: flex-start; background: var(--din-reserves-bg); font-weight: 700; color: var(--din-reserves-ink);
  &.is-x { background: color-mix(in oklch, var(--din-reserves-mark) 50%, var(--din-reserves-bg)); }
  &.is-sel { box-shadow: inset 3px 0 0 var(--din-reserves-ink); } }
.din-reserves__c {
  --dev: 0; --dv: 0;
  background: color-mix(in oklch, var(--din-reserves-ibnr) calc(var(--dev) * 13%), transparent);
  transition: background-color .3s, color .3s;
  animation: din-reserves-cell .5s var(--din-reserves-out) backwards; animation-delay: calc(var(--i) * 26ms);
  &.is-diag { font-weight: 750; box-shadow: inset 0 -2px 0 var(--din-reserves-ink); }
  &.is-proj { color: var(--din-reserves-faint); font-style: italic; background: repeating-linear-gradient(135deg, transparent 0 4px, var(--din-reserves-soft) 4px 5px); }
  &.is-ult { font-weight: 750; border-left: 1.5px solid var(--din-reserves-ink); background: var(--din-reserves-card); }
  &.is-x { box-shadow: inset 0 0 0 100px color-mix(in oklch, var(--din-reserves-mark) 32%, transparent); }
  &.is-x.is-diag { box-shadow: inset 0 0 0 100px color-mix(in oklch, var(--din-reserves-mark) 32%, transparent), inset 0 -2px 0 var(--din-reserves-ink); }
  &.is-sel { color: var(--din-reserves-ink); }
