}
/* factors view */
.din-reserves__f { cursor: pointer; display: flex; align-items: center; justify-content: flex-end; width: 100%; height: 100%; padding: 0 7px; font: inherit; transition: background-color .3s, color .3s;
  background: color-mix(in oklch, var(--dvc, var(--din-reserves-accent)) calc(var(--dv) * 30%), transparent);
